/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    iLBC_test.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "iLBC_define.h"
#include "iLBC_encode.h"
#include "iLBC_decode.h"

/* 実行時間の統計 */
#include <time.h>

#define ILBCNOOFWORDS_MAX   (NO_OF_BYTES_30MS/2)

/*----------------------------------------------------------------*
 *  エンコーダーのインターフェース関数
 *---------------------------------------------------------------*/

short encode(   /* (o) 符号化したバイト数 */
    iLBC_Enc_Inst_t *iLBCenc_inst,
                                /* (i/o) エンコーダーインスタンス */
    short *encoded_data,    /* (o) 符号化したバイト列 */
    short *data                 /* (i) 符号化する信号ブロック */
){
    float block[BLOCKL_MAX];
    int k;

    /* 信号をfloatに変換 */

    for (k=0; k<iLBCenc_inst->blockl; k++)
        block[k] = (float)data[k];

    /* 実際の符号化を行う */

    iLBC_encode((unsigned char *)encoded_data, block, iLBCenc_inst);


    return (iLBCenc_inst->no_of_bytes);
}

/*----------------------------------------------------------------*
 *  デコーダーのインターフェース関数
 *---------------------------------------------------------------*/

short decode(       /* (o) 復号したサンプル数 */
    iLBC_Dec_Inst_t *iLBCdec_inst,  /* (i/o) デコーダーインスタンス */
    short *decoded_data,        /* (o) 復号した信号ブロック */
    short *encoded_data,        /* (i) 符号化されたバイト列 */
    short mode                       /* (i) 0=PL、1=通常 */
){
    int k;
    float decblock[BLOCKL_MAX], dtmp;

    /* モードが有効か確認 */

    if (mode<0 || mode>1) {
        printf("\nERROR - Wrong mode - 0, 1 allowed\n"); exit(3);}

    /* ブロックの実際の復号を行う */

    iLBC_decode(decblock, (unsigned char *)encoded_data,
        iLBCdec_inst, mode);

    /* shortに変換 */
    for (k=0; k<iLBCdec_inst->blockl; k++){
        dtmp=decblock[k];

        if (dtmp<MIN_SAMPLE)
            dtmp=MIN_SAMPLE;
        else if (dtmp>MAX_SAMPLE)
            dtmp=MAX_SAMPLE;
        decoded_data[k] = (short) dtmp;
    }

    return (iLBCdec_inst->blockl);
}

/*---------------------------------------------------------------*
 *  iLBCの符号化と復号をテストするメインプログラム
 *
 *  使い方:
 *    exefile_name.exe <infile> <bytefile> <outfile> <channel>
 *
 *    <infile>   : 入力ファイル。エンコーダーに入れる音声（16ビットPCMファイル）
 *    <bytefile> : エンコーダーが出力するビットストリーム
 *    <outfile>  : 出力ファイル。復号した音声（16ビットPCMファイル）
 *    <channel>  : ビット誤りファイル。省略可（16ビット）
 *                     1 - パケットを正しく受信
 *                     0 - パケットロス
 *
 *--------------------------------------------------------------*/

int main(int argc, char* argv[])
{

    /* 実行時間の統計 */

    float starttime;
    float runtime;
    float outtime;

    FILE *ifileid,*efileid,*ofileid, *cfileid;
    short data[BLOCKL_MAX];
    short encoded_data[ILBCNOOFWORDS_MAX], decoded_data[BLOCKL_MAX];
    int len;
    short pli, mode;
    int blockcount = 0;
    int packetlosscount = 0;

    /* 構造体を作成 */
    iLBC_Enc_Inst_t Enc_Inst;
    iLBC_Dec_Inst_t Dec_Inst;
    /* 引数を取得してファイルを開く */

    if ((argc!=5) && (argc!=6)) {
        fprintf(stderr,
        "\n*-----------------------------------------------*\n");
        fprintf(stderr,
        "   %s <20,30> input encoded decoded (channel)\n\n",
            argv[0]);
        fprintf(stderr,
        "   mode    : Frame size for the encoding/decoding\n");
        fprintf(stderr,
        "                 20 - 20 ms\n");
        fprintf(stderr,
        "                 30 - 30 ms\n");
        fprintf(stderr,
        "   input   : Speech for encoder (16-bit pcm file)\n");
        fprintf(stderr,
        "   encoded : Encoded bit stream\n");
        fprintf(stderr,
        "   decoded : Decoded speech (16-bit pcm file)\n");
        fprintf(stderr,
        "   channel : Packet loss pattern, optional (16-bit)\n");
        fprintf(stderr,
        "                  1 - Packet received correctly\n");
        fprintf(stderr,
        "                  0 - Packet Lost\n");
        fprintf(stderr,
        "*-----------------------------------------------*\n\n");
        exit(1);
    }
    mode=atoi(argv[1]);
    if (mode != 20 && mode != 30) {
        fprintf(stderr,"Wrong mode %s, must be 20, or 30\n",
            argv[1]);
        exit(2);
    }
    if ( (ifileid=fopen(argv[2],"rb")) == NULL) {
        fprintf(stderr,"Cannot open input file %s\n", argv[2]);
        exit(2);}
    if ( (efileid=fopen(argv[3],"wb")) == NULL) {
        fprintf(stderr, "Cannot open encoded file %s\n",
            argv[3]); exit(1);}
    if ( (ofileid=fopen(argv[4],"wb")) == NULL) {
        fprintf(stderr, "Cannot open decoded file %s\n",
            argv[4]); exit(1);}
    if (argc==6) {
        if( (cfileid=fopen(argv[5],"rb")) == NULL) {
            fprintf(stderr, "Cannot open channel file %s\n",
                argv[5]);
            exit(1);
        }
    } else {
        cfileid=NULL;
    }

    /* 情報を表示 */

    fprintf(stderr, "\n");
    fprintf(stderr,
        "*---------------------------------------------------*\n");
    fprintf(stderr,
        "*                                                   *\n");
    fprintf(stderr,
        "*      iLBC test program                            *\n");
    fprintf(stderr,
        "*                                                   *\n");
    fprintf(stderr,
        "*                                                   *\n");
    fprintf(stderr,
        "*---------------------------------------------------*\n");
    fprintf(stderr,"\nMode           : %2d ms\n", mode);
    fprintf(stderr,"Input file     : %s\n", argv[2]);
    fprintf(stderr,"Encoded file   : %s\n", argv[3]);
    fprintf(stderr,"Output file    : %s\n", argv[4]);
    if (argc==6) {
        fprintf(stderr,"Channel file   : %s\n", argv[5]);
    }
    fprintf(stderr,"\n");

    /* 初期化 */

    initEncode(&Enc_Inst, mode);
    initDecode(&Dec_Inst, mode, 1);

    /* 実行時間の統計 */

    starttime=clock()/(float)CLOCKS_PER_SEC;

    /* 入力ブロックごとのループ */

    while (fread(data,sizeof(short),Enc_Inst.blockl,ifileid)==
            Enc_Inst.blockl) {

        blockcount++;

        /* 符号化 */
        fprintf(stderr, "--- Encoding block %i --- ",blockcount);
        len=encode(&Enc_Inst, encoded_data, data);
        fprintf(stderr, "\r");

        /* バイトファイルを書き出す */

        fwrite(encoded_data, sizeof(unsigned char), len, efileid);

        /* チャネルデータがあれば取得 */
        if (argc==6) {
            if (fread(&pli, sizeof(short), 1, cfileid)) {
                if ((pli!=0)&&(pli!=1)) {
                    fprintf(stderr, "Error in channel file\n");
                    exit(0);
                }
                if (pli==0) {
                    /* パケットロス -> フレームから情報を消す */
                    memset(encoded_data, 0,
                        sizeof(short)*ILBCNOOFWORDS_MAX);
                    packetlosscount++;
                }
            } else {
                fprintf(stderr, "Error. Channel file too short\n");
                exit(0);
            }
        } else {
            pli=1;
        }

        /* 復号 */

        fprintf(stderr, "--- Decoding block %i --- ",blockcount);

        len=decode(&Dec_Inst, decoded_data, encoded_data, pli);
        fprintf(stderr, "\r");

        /* 出力ファイルを書き出す */

        fwrite(decoded_data,sizeof(short),len,ofileid);
    }

    /* 実行時間の統計 */

    runtime = (float)(clock()/(float)CLOCKS_PER_SEC-starttime);
    outtime = (float)((float)blockcount*(float)mode/1000.0);
    printf("\n\nLength of speech file: %.1f s\n", outtime);
    printf("Packet loss          : %.1f%%\n",
        100.0*(float)packetlosscount/(float)blockcount);
    printf("Time to run iLBC     :");
    printf(" %.1f s (%.1f %% of realtime)\n\n", runtime,
        (100*runtime/outtime));

    /* ファイルを閉じる */

    fclose(ifileid);  fclose(efileid); fclose(ofileid);
    if (argc==6) {
        fclose(cfileid);
    }
    return(0);
}

/******************************************************************
iLBC Speech Coder ANSI-C Source Code
iLBC_encode.h
Copyright (C) The Internet Society (2004). All Rights Reserved.
******************************************************************/
#ifndef __iLBC_ILBCENCODE_H #define __iLBC_ILBCENCODE_H
#include "iLBC_define.h"
short initEncode( /* (o) 符号化した バイト数 */ iLBC_Enc_Inst_t *iLBCenc_inst, /* (i/o) エンコーダーインスタンス */ int mode /* (i) フレームサイズのモード */ );
void iLBC_encode(
unsigned char *bytes, /* (o) iLBCの符号化データビット */ float *block, /* (o) 符号化する 音声ベクトル */ iLBC_Enc_Inst_t *iLBCenc_inst /* (i/o) エンコーダー全体の 状態 */ );
#endif

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    iLBC_encode.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "iLBC_define.h"
#include "LPCencode.h"
#include "FrameClassify.h"
#include "StateSearchW.h"
#include "StateConstructW.h"
#include "helpfun.h"
#include "constants.h"
#include "packing.h"
#include "iCBSearch.h"
#include "iCBConstruct.h"
#include "hpInput.h"
#include "anaFilter.h"
#include "syntFilter.h"

/*----------------------------------------------------------------*
 *  エンコーダーインスタンスの初期化
 *---------------------------------------------------------------*/

short initEncode(                   /* (o) 符号化した
                                           バイト数 */
    iLBC_Enc_Inst_t *iLBCenc_inst,  /* (i/o) エンコーダーインスタンス */
    int mode                    /* (i) フレームサイズのモード */
){
    iLBCenc_inst->mode = mode;
    if (mode==30) {
        iLBCenc_inst->blockl = BLOCKL_30MS;
        iLBCenc_inst->nsub = NSUB_30MS;
        iLBCenc_inst->nasub = NASUB_30MS;
        iLBCenc_inst->lpc_n = LPC_N_30MS;
        iLBCenc_inst->no_of_bytes = NO_OF_BYTES_30MS;
        iLBCenc_inst->no_of_words = NO_OF_WORDS_30MS;
        iLBCenc_inst->state_short_len=STATE_SHORT_LEN_30MS;
        /* ULPの初期化 */
        iLBCenc_inst->ULP_inst=&ULP_30msTbl;
    }
    else if (mode==20) {
        iLBCenc_inst->blockl = BLOCKL_20MS;
        iLBCenc_inst->nsub = NSUB_20MS;
        iLBCenc_inst->nasub = NASUB_20MS;
        iLBCenc_inst->lpc_n = LPC_N_20MS;
        iLBCenc_inst->no_of_bytes = NO_OF_BYTES_20MS;
        iLBCenc_inst->no_of_words = NO_OF_WORDS_20MS;
        iLBCenc_inst->state_short_len=STATE_SHORT_LEN_20MS;
        /* ULPの初期化 */
        iLBCenc_inst->ULP_inst=&ULP_20msTbl;
    }
    else {
        exit(2);
    }

    memset((*iLBCenc_inst).anaMem, 0,
        LPC_FILTERORDER*sizeof(float));
    memcpy((*iLBCenc_inst).lsfold, lsfmeanTbl,
        LPC_FILTERORDER*sizeof(float));
    memcpy((*iLBCenc_inst).lsfdeqold, lsfmeanTbl,
        LPC_FILTERORDER*sizeof(float));
    memset((*iLBCenc_inst).lpc_buffer, 0,
        (LPC_LOOKBACK+BLOCKL_MAX)*sizeof(float));
    memset((*iLBCenc_inst).hpimem, 0, 4*sizeof(float));

    return (iLBCenc_inst->no_of_bytes);
}

/*----------------------------------------------------------------*
 *  エンコーダーのメイン関数
 *---------------------------------------------------------------*/

void iLBC_encode(
    unsigned char *bytes,           /* (o) iLBCの符号化データビット */
    float *block,                   /* (o) 符号化する
                                           音声ベクトル */
    iLBC_Enc_Inst_t *iLBCenc_inst   /* (i/o) エンコーダー全体の
                                           状態 */
){

    float data[BLOCKL_MAX];
    float residual[BLOCKL_MAX], reverseResidual[BLOCKL_MAX];

    int start, idxForMax, idxVec[STATE_LEN];
    float reverseDecresidual[BLOCKL_MAX], mem[CB_MEML];
    int n, k, meml_gotten, Nfor, Nback, i, pos;
    int gain_index[CB_NSTAGES*NASUB_MAX],
        extra_gain_index[CB_NSTAGES];
    int cb_index[CB_NSTAGES*NASUB_MAX],extra_cb_index[CB_NSTAGES];
    int lsf_i[LSF_NSPLIT*LPC_N_MAX];
    unsigned char *pbytes;
    int diff, start_pos, state_first;
    float en1, en2;
    int index, ulp, firstpart;
    int subcount, subframe;
    float weightState[LPC_FILTERORDER];
    float syntdenum[NSUB_MAX*(LPC_FILTERORDER+1)];
    float weightdenum[NSUB_MAX*(LPC_FILTERORDER+1)];
    float decresidual[BLOCKL_MAX];

    /* この関数の呼び出し前に行われていなければ、入力信号に
           ハイパスフィルターをかける */

    hpInput(block, iLBCenc_inst->blockl,
                data, (*iLBCenc_inst).hpimem);

    /* そうでなければ単にコピーする */

    /*memcpy(data,block,iLBCenc_inst->blockl*sizeof(float));*/

    /* ハイパスフィルターをかけた入力データのLPC */

    LPCencode(syntdenum, weightdenum, lsf_i, data, iLBCenc_inst);


    /* 逆フィルターで残差を得る */

    for (n=0; n<iLBCenc_inst->nsub; n++) {
        anaFilter(&data[n*SUBL], &syntdenum[n*(LPC_FILTERORDER+1)],
            SUBL, &residual[n*SUBL], iLBCenc_inst->anaMem);
    }

    /* 状態の位置を見つける */

    start = FrameClassify(iLBCenc_inst, residual);

    /* 状態を2つのサブフレームの前側と後側のどちらに置くべきか
    確認する */

    diff = STATE_LEN - iLBCenc_inst->state_short_len;
    en1 = 0;
    index = (start-1)*SUBL;
    for (i = 0; i < iLBCenc_inst->state_short_len; i++) {
        en1 += residual[index+i]*residual[index+i];
    }
    en2 = 0;
    index = (start-1)*SUBL+diff;
    for (i = 0; i < iLBCenc_inst->state_short_len; i++) {
        en2 += residual[index+i]*residual[index+i];
    }


    if (en1 > en2) {
        state_first = 1;
        start_pos = (start-1)*SUBL;
    } else {
        state_first = 0;
        start_pos = (start-1)*SUBL + diff;
    }

    /* 状態のスカラー量子化 */

    StateSearchW(iLBCenc_inst, &residual[start_pos],
        &syntdenum[(start-1)*(LPC_FILTERORDER+1)],
        &weightdenum[(start-1)*(LPC_FILTERORDER+1)], &idxForMax,
        idxVec, iLBCenc_inst->state_short_len, state_first);

    StateConstructW(idxForMax, idxVec,
        &syntdenum[(start-1)*(LPC_FILTERORDER+1)],
        &decresidual[start_pos], iLBCenc_inst->state_short_len);

    /* 状態内の予測量子化 */

    if (state_first) { /* 適応部分を末尾に置く */

        /* メモリーを準備 */

        memset(mem, 0,
            (CB_MEML-iLBCenc_inst->state_short_len)*sizeof(float));
        memcpy(mem+CB_MEML-iLBCenc_inst->state_short_len,
            decresidual+start_pos,
            iLBCenc_inst->state_short_len*sizeof(float));
        memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

        /* サブフレームを符号化 */

        iCBSearch(iLBCenc_inst, extra_cb_index, extra_gain_index,
            &residual[start_pos+iLBCenc_inst->state_short_len],
            mem+CB_MEML-stMemLTbl,
            stMemLTbl, diff, CB_NSTAGES,
            &weightdenum[start*(LPC_FILTERORDER+1)],
            weightState, 0);

        /* 復号ベクトルを構成 */

        iCBConstruct(
            &decresidual[start_pos+iLBCenc_inst->state_short_len],
            extra_cb_index, extra_gain_index,
            mem+CB_MEML-stMemLTbl,
            stMemLTbl, diff, CB_NSTAGES);

    }
    else { /* 適応部分を先頭に置く */

        /* 予測用に反転したベクトルを作成 */

        for (k=0; k<diff; k++) {
            reverseResidual[k] = residual[(start+1)*SUBL-1
                -(k+iLBCenc_inst->state_short_len)];
        }

        /* メモリーを準備 */

        meml_gotten = iLBCenc_inst->state_short_len;
        for (k=0; k<meml_gotten; k++) {
            mem[CB_MEML-1-k] = decresidual[start_pos + k];
        }
        memset(mem, 0, (CB_MEML-k)*sizeof(float));
        memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

        /* サブフレームを符号化 */

        iCBSearch(iLBCenc_inst, extra_cb_index, extra_gain_index,
            reverseResidual, mem+CB_MEML-stMemLTbl, stMemLTbl,
            diff, CB_NSTAGES,
            &weightdenum[(start-1)*(LPC_FILTERORDER+1)],
            weightState, 0);

        /* 復号ベクトルを構成 */

        iCBConstruct(reverseDecresidual, extra_cb_index,
            extra_gain_index, mem+CB_MEML-stMemLTbl, stMemLTbl,
            diff, CB_NSTAGES);

        /* 反転したベクトルから復号残差を得る */

        for (k=0; k<diff; k++) {
            decresidual[start_pos-1-k] = reverseDecresidual[k];
        }
    }

    /* 予測したサブフレームのカウンター */

    subcount=0;

    /* サブフレームの前方予測 */

    Nfor = iLBCenc_inst->nsub-start-1;


    if ( Nfor > 0 ) {

        /* メモリーを準備 */

        memset(mem, 0, (CB_MEML-STATE_LEN)*sizeof(float));
        memcpy(mem+CB_MEML-STATE_LEN, decresidual+(start-1)*SUBL,
            STATE_LEN*sizeof(float));
        memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

        /* 符号化するサブフレームごとのループ */

        for (subframe=0; subframe<Nfor; subframe++) {

            /* サブフレームを符号化 */

            iCBSearch(iLBCenc_inst, cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                &residual[(start+1+subframe)*SUBL],
                mem+CB_MEML-memLfTbl[subcount],
                memLfTbl[subcount], SUBL, CB_NSTAGES,
                &weightdenum[(start+1+subframe)*
                            (LPC_FILTERORDER+1)],
                weightState, subcount+1);

            /* 復号ベクトルを構成 */

            iCBConstruct(&decresidual[(start+1+subframe)*SUBL],
                cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                mem+CB_MEML-memLfTbl[subcount],
                memLfTbl[subcount], SUBL, CB_NSTAGES);

            /* メモリーを更新 */

            memcpy(mem, mem+SUBL, (CB_MEML-SUBL)*sizeof(float));
            memcpy(mem+CB_MEML-SUBL,
                &decresidual[(start+1+subframe)*SUBL],
                SUBL*sizeof(float));
            memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

            subcount++;
        }
    }


    /* サブフレームの後方予測 */

    Nback = start-1;


    if ( Nback > 0 ) {

        /* 逆順のベクトルを作成 */

        for (n=0; n<Nback; n++) {
            for (k=0; k<SUBL; k++) {
                reverseResidual[n*SUBL+k] =
                    residual[(start-1)*SUBL-1-n*SUBL-k];
                reverseDecresidual[n*SUBL+k] =
                    decresidual[(start-1)*SUBL-1-n*SUBL-k];
            }
        }

        /* メモリーを準備 */

        meml_gotten = SUBL*(iLBCenc_inst->nsub+1-start);


        if ( meml_gotten > CB_MEML ) {
            meml_gotten=CB_MEML;
        }
        for (k=0; k<meml_gotten; k++) {
            mem[CB_MEML-1-k] = decresidual[(start-1)*SUBL + k];
        }
        memset(mem, 0, (CB_MEML-k)*sizeof(float));
        memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

        /* 符号化するサブフレームごとのループ */

        for (subframe=0; subframe<Nback; subframe++) {

            /* サブフレームを符号化 */

            iCBSearch(iLBCenc_inst, cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                &reverseResidual[subframe*SUBL],
                mem+CB_MEML-memLfTbl[subcount],
                memLfTbl[subcount], SUBL, CB_NSTAGES,
                &weightdenum[(start-2-subframe)*
                            (LPC_FILTERORDER+1)],
                weightState, subcount+1);

            /* 復号ベクトルを構成 */

            iCBConstruct(&reverseDecresidual[subframe*SUBL],
                cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                mem+CB_MEML-memLfTbl[subcount],
                memLfTbl[subcount], SUBL, CB_NSTAGES);

            /* メモリーを更新 */

            memcpy(mem, mem+SUBL, (CB_MEML-SUBL)*sizeof(float));
            memcpy(mem+CB_MEML-SUBL,
                &reverseDecresidual[subframe*SUBL],
                SUBL*sizeof(float));
            memset(weightState, 0, LPC_FILTERORDER*sizeof(float));

            subcount++;

        }

        /* 反転したベクトルから復号残差を得る */

        for (i=0; i<SUBL*Nback; i++) {
            decresidual[SUBL*Nback - i - 1] =
                reverseDecresidual[i];
        }
    }
    /* 符号化部分の終わり */

    /* インデックスを調整 */
    index_conv_enc(cb_index);

    /* バイト列にパック */

    pbytes=bytes;
    pos=0;

    /* 3つのULPクラスごとのループ */

    for (ulp=0; ulp<3; ulp++) {
        /* LSF */
        for (k=0; k<LSF_NSPLIT*iLBCenc_inst->lpc_n; k++) {
            packsplit(&lsf_i[k], &firstpart, &lsf_i[k],
                iLBCenc_inst->ULP_inst->lsf_bits[k][ulp],
                iLBCenc_inst->ULP_inst->lsf_bits[k][ulp]+
                iLBCenc_inst->ULP_inst->lsf_bits[k][ulp+1]+
                iLBCenc_inst->ULP_inst->lsf_bits[k][ulp+2]);
            dopack( &pbytes, firstpart,
                iLBCenc_inst->ULP_inst->lsf_bits[k][ulp], &pos);
        }

        /* 開始ブロックの情報 */

        packsplit(&start, &firstpart, &start,
            iLBCenc_inst->ULP_inst->start_bits[ulp],
            iLBCenc_inst->ULP_inst->start_bits[ulp]+
            iLBCenc_inst->ULP_inst->start_bits[ulp+1]+
            iLBCenc_inst->ULP_inst->start_bits[ulp+2]);
        dopack( &pbytes, firstpart,
            iLBCenc_inst->ULP_inst->start_bits[ulp], &pos);

        packsplit(&state_first, &firstpart, &state_first,
            iLBCenc_inst->ULP_inst->startfirst_bits[ulp],
            iLBCenc_inst->ULP_inst->startfirst_bits[ulp]+
            iLBCenc_inst->ULP_inst->startfirst_bits[ulp+1]+
            iLBCenc_inst->ULP_inst->startfirst_bits[ulp+2]);
        dopack( &pbytes, firstpart,
            iLBCenc_inst->ULP_inst->startfirst_bits[ulp], &pos);

        packsplit(&idxForMax, &firstpart, &idxForMax,
            iLBCenc_inst->ULP_inst->scale_bits[ulp],
            iLBCenc_inst->ULP_inst->scale_bits[ulp]+
            iLBCenc_inst->ULP_inst->scale_bits[ulp+1]+
            iLBCenc_inst->ULP_inst->scale_bits[ulp+2]);
        dopack( &pbytes, firstpart,
            iLBCenc_inst->ULP_inst->scale_bits[ulp], &pos);

        for (k=0; k<iLBCenc_inst->state_short_len; k++) {
            packsplit(idxVec+k, &firstpart, idxVec+k,
                iLBCenc_inst->ULP_inst->state_bits[ulp],
                iLBCenc_inst->ULP_inst->state_bits[ulp]+
                iLBCenc_inst->ULP_inst->state_bits[ulp+1]+
                iLBCenc_inst->ULP_inst->state_bits[ulp+2]);
            dopack( &pbytes, firstpart,
                iLBCenc_inst->ULP_inst->state_bits[ulp], &pos);
        }
        /* 23/22（20ms/30ms）サンプルのブロック */

        for (k=0;k<CB_NSTAGES;k++) {
            packsplit(extra_cb_index+k, &firstpart,
                extra_cb_index+k,
                iLBCenc_inst->ULP_inst->extra_cb_index[k][ulp],
                iLBCenc_inst->ULP_inst->extra_cb_index[k][ulp]+
                iLBCenc_inst->ULP_inst->extra_cb_index[k][ulp+1]+
                iLBCenc_inst->ULP_inst->extra_cb_index[k][ulp+2]);
            dopack( &pbytes, firstpart,
                iLBCenc_inst->ULP_inst->extra_cb_index[k][ulp],
                &pos);
        }

        for (k=0;k<CB_NSTAGES;k++) {
            packsplit(extra_gain_index+k, &firstpart,
                extra_gain_index+k,
                iLBCenc_inst->ULP_inst->extra_cb_gain[k][ulp],
                iLBCenc_inst->ULP_inst->extra_cb_gain[k][ulp]+
                iLBCenc_inst->ULP_inst->extra_cb_gain[k][ulp+1]+
                iLBCenc_inst->ULP_inst->extra_cb_gain[k][ulp+2]);
            dopack( &pbytes, firstpart,
                iLBCenc_inst->ULP_inst->extra_cb_gain[k][ulp],
                &pos);
        }

        /* 2/4個（20ms/30ms）の40サンプルのサブブロック */

        for (i=0; i<iLBCenc_inst->nasub; i++) {
            for (k=0; k<CB_NSTAGES; k++) {
                packsplit(cb_index+i*CB_NSTAGES+k, &firstpart,
                    cb_index+i*CB_NSTAGES+k,
                    iLBCenc_inst->ULP_inst->cb_index[i][k][ulp],
                    iLBCenc_inst->ULP_inst->cb_index[i][k][ulp]+
                    iLBCenc_inst->ULP_inst->cb_index[i][k][ulp+1]+
                    iLBCenc_inst->ULP_inst->cb_index[i][k][ulp+2]);
                dopack( &pbytes, firstpart,
                    iLBCenc_inst->ULP_inst->cb_index[i][k][ulp],
                    &pos);
            }
        }

        for (i=0; i<iLBCenc_inst->nasub; i++) {
            for (k=0; k<CB_NSTAGES; k++) {
                packsplit(gain_index+i*CB_NSTAGES+k, &firstpart,
                    gain_index+i*CB_NSTAGES+k,
                    iLBCenc_inst->ULP_inst->cb_gain[i][k][ulp],
                    iLBCenc_inst->ULP_inst->cb_gain[i][k][ulp]+
                    iLBCenc_inst->ULP_inst->cb_gain[i][k][ulp+1]+
                    iLBCenc_inst->ULP_inst->cb_gain[i][k][ulp+2]);
                dopack( &pbytes, firstpart,
                    iLBCenc_inst->ULP_inst->cb_gain[i][k][ulp],
                    &pos);
            }
        }
    }

    /* 最後のビットを0にする（そうしないとデコーダーは
       喪失したフレームとして扱う） */
    dopack( &pbytes, 0, 1, &pos);
}

