void iLBC_decode( float *decblock, /* (o) 復号した信号ブロック */ unsigned char *bytes, /* (i) 符号化された信号ビット */ iLBC_Dec_Inst_t *iLBCdec_inst, /* (i/o) デコーダーの状態を 保持する構造体 */ int mode /* (i) 0: 不良パケット、PLC、 1: 通常 */ );
