/*----------------------------------------------------------------*
 *  デコーダーインスタンスの初期化
 *---------------------------------------------------------------*/

short initDecode(                   /* (o) 復号された
                                           サンプル数 */
    iLBC_Dec_Inst_t *iLBCdec_inst,  /* (i/o) デコーダーインスタンス */
    int mode,                       /* (i) フレームサイズのモード */
    int use_enhancer                /* (i) 1でエンハンサーを使用、
                                           0でエンハンサーなしで
                                             実行 */
){
    int i;

    iLBCdec_inst->mode = mode;
    if (mode==30) {
        iLBCdec_inst->blockl = BLOCKL_30MS;
        iLBCdec_inst->nsub = NSUB_30MS;
        iLBCdec_inst->nasub = NASUB_30MS;
        iLBCdec_inst->lpc_n = LPC_N_30MS;
        iLBCdec_inst->no_of_bytes = NO_OF_BYTES_30MS;
        iLBCdec_inst->no_of_words = NO_OF_WORDS_30MS;
        iLBCdec_inst->state_short_len=STATE_SHORT_LEN_30MS;
        /* ULPの初期化 */
        iLBCdec_inst->ULP_inst=&ULP_30msTbl;
    }
    else if (mode==20) {
        iLBCdec_inst->blockl = BLOCKL_20MS;
        iLBCdec_inst->nsub = NSUB_20MS;
        iLBCdec_inst->nasub = NASUB_20MS;
        iLBCdec_inst->lpc_n = LPC_N_20MS;
        iLBCdec_inst->no_of_bytes = NO_OF_BYTES_20MS;
        iLBCdec_inst->no_of_words = NO_OF_WORDS_20MS;
        iLBCdec_inst->state_short_len=STATE_SHORT_LEN_20MS;
        /* ULPの初期化 */
        iLBCdec_inst->ULP_inst=&ULP_20msTbl;
    }
    else {
        exit(2);
    }

    memset(iLBCdec_inst->syntMem, 0,
        LPC_FILTERORDER*sizeof(float));
    memcpy((*iLBCdec_inst).lsfdeqold, lsfmeanTbl,
        LPC_FILTERORDER*sizeof(float));

    memset(iLBCdec_inst->old_syntdenum, 0,
        ((LPC_FILTERORDER + 1)*NSUB_MAX)*sizeof(float));
    for (i=0; i<NSUB_MAX; i++)
        iLBCdec_inst->old_syntdenum[i*(LPC_FILTERORDER+1)]=1.0;

    iLBCdec_inst->last_lag = 20;

    iLBCdec_inst->prevLag = 120;
    iLBCdec_inst->per = 0.0;
    iLBCdec_inst->consPLICount = 0;
    iLBCdec_inst->prevPLI = 0;
    iLBCdec_inst->prevLpc[0] = 1.0;
    memset(iLBCdec_inst->prevLpc+1,0,
        LPC_FILTERORDER*sizeof(float));
    memset(iLBCdec_inst->prevResidual, 0, BLOCKL_MAX*sizeof(float));
    iLBCdec_inst->seed=777;
    memset(iLBCdec_inst->hpomem, 0, 4*sizeof(float));

    iLBCdec_inst->use_enhancer = use_enhancer;
    memset(iLBCdec_inst->enh_buf, 0, ENH_BUFL*sizeof(float));
    for (i=0;i<ENH_NBLOCKS_TOT;i++)
        iLBCdec_inst->enh_period[i]=(float)40.0;

    iLBCdec_inst->prev_enh_pl = 0;

    return (iLBCdec_inst->blockl);
}

/*----------------------------------------------------------------*
 *  フレームの残差を復号する関数（iLBC_decodeのサブルーチン）
 *---------------------------------------------------------------*/

void Decode(
    iLBC_Dec_Inst_t *iLBCdec_inst,  /* (i/o) デコーダーの状態を表す
                                             構造体 */
    float *decresidual,             /* (o) 復号した残差フレーム */
    int start,                      /* (i) 開始状態の
                                           位置 */
    int idxForMax,                  /* (i) 最大値の
                                           コードブックインデックス */
    int *idxVec,                /* (i) 開始状態内の
                                           サンプルの
                                           コードブックインデックス */
    float *syntdenum,               /* (i) 復号した合成フィルターの
                                           係数 */
    int *cb_index,                  /* (i) 適応コードブックの
                                           インデックス */
    int *gain_index,            /* (i) 対応するゲインの
                                           インデックス */
    int *extra_cb_index,        /* (i) 開始状態の適応
                                           コードブック部分の
                                           インデックス */
    int *extra_gain_index,          /* (i) 対応するゲインの
                                           インデックス */
    int state_first                 /* (i) 開始状態の非適応部分が
                                           先に来る場合は1、
                                           その部分が後に来る
                                           場合は0 */
){
    float reverseDecresidual[BLOCKL_MAX], mem[CB_MEML];
    int k, meml_gotten, Nfor, Nback, i;
    int diff, start_pos;
    int subcount, subframe;
    diff = STATE_LEN - iLBCdec_inst->state_short_len;

    if (state_first == 1) {
        start_pos = (start-1)*SUBL;
    } else {
        start_pos = (start-1)*SUBL + diff;
    }

    /* 開始状態のスカラー部分を復号 */

    StateConstructW(idxForMax, idxVec,
        &syntdenum[(start-1)*(LPC_FILTERORDER+1)],
        &decresidual[start_pos], iLBCdec_inst->state_short_len);


    if (state_first) { /* 適応部分を末尾に置く */

        /* メモリーを準備 */

        memset(mem, 0,
            (CB_MEML-iLBCdec_inst->state_short_len)*sizeof(float));
        memcpy(mem+CB_MEML-iLBCdec_inst->state_short_len,
            decresidual+start_pos,
            iLBCdec_inst->state_short_len*sizeof(float));

        /* 復号ベクトルを構築 */

        iCBConstruct(
            &decresidual[start_pos+iLBCdec_inst->state_short_len],
            extra_cb_index, extra_gain_index, mem+CB_MEML-stMemLTbl,
            stMemLTbl, diff, CB_NSTAGES);

    }
    else {/* 適応部分を先頭に置く */

        /* 予測用に反転したベクトルを作成 */

        for (k=0; k<diff; k++) {
            reverseDecresidual[k] =
                decresidual[(start+1)*SUBL-1-
                        (k+iLBCdec_inst->state_short_len)];
        }

        /* メモリーを準備 */

        meml_gotten = iLBCdec_inst->state_short_len;
        for (k=0; k<meml_gotten; k++){
            mem[CB_MEML-1-k] = decresidual[start_pos + k];
        }
        memset(mem, 0, (CB_MEML-k)*sizeof(float));

        /* 復号ベクトルを構築 */

        iCBConstruct(reverseDecresidual, extra_cb_index,
            extra_gain_index, mem+CB_MEML-stMemLTbl, stMemLTbl,
            diff, CB_NSTAGES);

        /* 反転したベクトルから復号した残差を取得 */

        for (k=0; k<diff; k++) {
            decresidual[start_pos-1-k] = reverseDecresidual[k];
        }
    }

    /* 予測したサブフレームのカウンター */

    subcount=0;

    /* サブフレームの前方予測 */

    Nfor = iLBCdec_inst->nsub-start-1;

    if ( Nfor > 0 ){

        /* メモリーを準備 */

        memset(mem, 0, (CB_MEML-STATE_LEN)*sizeof(float));
        memcpy(mem+CB_MEML-STATE_LEN, decresidual+(start-1)*SUBL,
            STATE_LEN*sizeof(float));

        /* 符号化するサブフレームをループ */

        for (subframe=0; subframe<Nfor; subframe++) {

            /* 復号ベクトルを構築 */

            iCBConstruct(&decresidual[(start+1+subframe)*SUBL],
                cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                mem+CB_MEML-memLfTbl[subcount],
                memLfTbl[subcount], SUBL, CB_NSTAGES);

            /* メモリーを更新 */

            memcpy(mem, mem+SUBL, (CB_MEML-SUBL)*sizeof(float));
            memcpy(mem+CB_MEML-SUBL,
                &decresidual[(start+1+subframe)*SUBL],
                SUBL*sizeof(float));

            subcount++;

        }

    }

    /* サブフレームの後方予測 */

    Nback = start-1;

    if ( Nback > 0 ) {

        /* メモリーを準備 */

        meml_gotten = SUBL*(iLBCdec_inst->nsub+1-start);

        if ( meml_gotten > CB_MEML ) {
            meml_gotten=CB_MEML;
        }
        for (k=0; k<meml_gotten; k++) {
            mem[CB_MEML-1-k] = decresidual[(start-1)*SUBL + k];
        }
        memset(mem, 0, (CB_MEML-k)*sizeof(float));

        /* 復号するサブフレームをループ */

        for (subframe=0; subframe<Nback; subframe++) {

            /* 復号ベクトルを構築 */

            iCBConstruct(&reverseDecresidual[subframe*SUBL],
                cb_index+subcount*CB_NSTAGES,
                gain_index+subcount*CB_NSTAGES,
                mem+CB_MEML-memLfTbl[subcount], memLfTbl[subcount],
                SUBL, CB_NSTAGES);

            /* メモリーを更新 */

            memcpy(mem, mem+SUBL, (CB_MEML-SUBL)*sizeof(float));
            memcpy(mem+CB_MEML-SUBL,
                &reverseDecresidual[subframe*SUBL],
                SUBL*sizeof(float));

            subcount++;
        }
        /* 反転したベクトルから復号した残差を取得 */

        for (i=0; i<SUBL*Nback; i++)
            decresidual[SUBL*Nback - i - 1] =
            reverseDecresidual[i];
    }
}

/*----------------------------------------------------------------*
 *  デコーダーのメイン関数
 *---------------------------------------------------------------*/

void iLBC_decode(
    float *decblock,            /* (o) 復号した信号ブロック */
    unsigned char *bytes,           /* (i) 符号化した信号のビット */
    iLBC_Dec_Inst_t *iLBCdec_inst,  /* (i/o) デコーダーの状態を表す
                                             構造体 */
    int mode                    /* (i) 0: 不良パケット、PLC、
                                           1: 通常 */
){
    float data[BLOCKL_MAX];
    float lsfdeq[LPC_FILTERORDER*LPC_N_MAX];
    float PLCresidual[BLOCKL_MAX], PLClpc[LPC_FILTERORDER + 1];
    float zeros[BLOCKL_MAX], one[LPC_FILTERORDER + 1];
    int k, i, start, idxForMax, pos, lastpart, ulp;
    int lag, ilag;
    float cc, maxcc;
    int idxVec[STATE_LEN];
    int check;
    int gain_index[NASUB_MAX*CB_NSTAGES],
        extra_gain_index[CB_NSTAGES];
    int cb_index[CB_NSTAGES*NASUB_MAX], extra_cb_index[CB_NSTAGES];
    int lsf_i[LSF_NSPLIT*LPC_N_MAX];
    int state_first;
    int last_bit;
    unsigned char *pbytes;
    float weightdenum[(LPC_FILTERORDER + 1)*NSUB_MAX];
    int order_plus_one;
    float syntdenum[NSUB_MAX*(LPC_FILTERORDER+1)];
    float decresidual[BLOCKL_MAX];

    if (mode>0) { /* データは正常 */

        /* データを復号 */

        pbytes=bytes;
        pos=0;
        /* 復号の前にすべてをゼロにする */

        for (k=0; k<LSF_NSPLIT*LPC_N_MAX; k++) {
            lsf_i[k]=0;
        }
        start=0;
        state_first=0;
        idxForMax=0;
        for (k=0; k<iLBCdec_inst->state_short_len; k++) {
            idxVec[k]=0;
        }
        for (k=0; k<CB_NSTAGES; k++) {
            extra_cb_index[k]=0;
        }
        for (k=0; k<CB_NSTAGES; k++) {
            extra_gain_index[k]=0;
        }
        for (i=0; i<iLBCdec_inst->nasub; i++) {
            for (k=0; k<CB_NSTAGES; k++) {
                cb_index[i*CB_NSTAGES+k]=0;
            }
        }
        for (i=0; i<iLBCdec_inst->nasub; i++) {
            for (k=0; k<CB_NSTAGES; k++) {
                gain_index[i*CB_NSTAGES+k]=0;
            }
        }

        /* ULPクラスをループ */

        for (ulp=0; ulp<3; ulp++) {

            /* LSF */
            for (k=0; k<LSF_NSPLIT*iLBCdec_inst->lpc_n; k++){
                unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->lsf_bits[k][ulp], &pos);
                packcombine(&lsf_i[k], lastpart,
                    iLBCdec_inst->ULP_inst->lsf_bits[k][ulp]);
            }

            /* 開始ブロックの情報 */

            unpack( &pbytes, &lastpart,
                iLBCdec_inst->ULP_inst->start_bits[ulp], &pos);
            packcombine(&start, lastpart,
                iLBCdec_inst->ULP_inst->start_bits[ulp]);

            unpack( &pbytes, &lastpart,
                iLBCdec_inst->ULP_inst->startfirst_bits[ulp], &pos);
            packcombine(&state_first, lastpart,
                iLBCdec_inst->ULP_inst->startfirst_bits[ulp]);

            unpack( &pbytes, &lastpart,
                iLBCdec_inst->ULP_inst->scale_bits[ulp], &pos);
            packcombine(&idxForMax, lastpart,
                iLBCdec_inst->ULP_inst->scale_bits[ulp]);

            for (k=0; k<iLBCdec_inst->state_short_len; k++) {
                unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->state_bits[ulp], &pos);
                packcombine(idxVec+k, lastpart,
                    iLBCdec_inst->ULP_inst->state_bits[ulp]);
            }

            /* 23/22（20ms/30ms）サンプルのブロック */

            for (k=0; k<CB_NSTAGES; k++) {
                unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->extra_cb_index[k][ulp],
                    &pos);
                packcombine(extra_cb_index+k, lastpart,
                    iLBCdec_inst->ULP_inst->extra_cb_index[k][ulp]);
            }
            for (k=0; k<CB_NSTAGES; k++) {
                unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->extra_cb_gain[k][ulp],
                    &pos);
                packcombine(extra_gain_index+k, lastpart,
                    iLBCdec_inst->ULP_inst->extra_cb_gain[k][ulp]);
            }

            /* 2個/4個（20ms/30ms）の40サンプルのサブブロック */

            for (i=0; i<iLBCdec_inst->nasub; i++) {
                for (k=0; k<CB_NSTAGES; k++) {
                    unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->cb_index[i][k][ulp],
                        &pos);
                    packcombine(cb_index+i*CB_NSTAGES+k, lastpart,
                    iLBCdec_inst->ULP_inst->cb_index[i][k][ulp]);
                }
            }

            for (i=0; i<iLBCdec_inst->nasub; i++) {
                for (k=0; k<CB_NSTAGES; k++) {
                    unpack( &pbytes, &lastpart,
                    iLBCdec_inst->ULP_inst->cb_gain[i][k][ulp],
                        &pos);
                    packcombine(gain_index+i*CB_NSTAGES+k, lastpart,
                        iLBCdec_inst->ULP_inst->cb_gain[i][k][ulp]);
                }
            }
        }
        /* 最後のビットを取り出す。これが1の場合は、空または
           消失したフレームであることを示す */
        unpack( &pbytes, &last_bit, 1, &pos);

        /* ビット誤りや空または消失したフレームを確認 */
        if (start<1)
            mode = 0;
        if (iLBCdec_inst->mode==20 && start>3)
            mode = 0;
        if (iLBCdec_inst->mode==30 && start>5)
            mode = 0;
        if (last_bit==1)
            mode = 0;

        if (mode==1) { /* ビット誤りは検出されなかったので、
                          復号を続ける */

            /* インデックスを調整 */
            index_conv_dec(cb_index);

            /* LSFを復号 */

            SimplelsfDEQ(lsfdeq, lsf_i, iLBCdec_inst->lpc_n);
            check=LSF_check(lsfdeq, LPC_FILTERORDER,
                iLBCdec_inst->lpc_n);
            DecoderInterpolateLSF(syntdenum, weightdenum,
                lsfdeq, LPC_FILTERORDER, iLBCdec_inst);

            Decode(iLBCdec_inst, decresidual, start, idxForMax,
                idxVec, syntdenum, cb_index, gain_index,
                extra_cb_index, extra_gain_index,
                state_first);

            /* 将来の消失に備えてPLCを準備！ */

            doThePLC(PLCresidual, PLClpc, 0, decresidual,
                syntdenum +
                (LPC_FILTERORDER + 1)*(iLBCdec_inst->nsub - 1),
                (*iLBCdec_inst).last_lag, iLBCdec_inst);
            memcpy(decresidual, PLCresidual,
                iLBCdec_inst->blockl*sizeof(float));
        }

    }

    if (mode == 0) {
        /* データが不良（PLCの呼び出しが行われたか、
         * 深刻なビット誤りが検出された）
         */

        /* パケットロス隠蔽 */

        memset(zeros, 0, BLOCKL_MAX*sizeof(float));

        one[0] = 1;
        memset(one+1, 0, LPC_FILTERORDER*sizeof(float));

        start=0;

        doThePLC(PLCresidual, PLClpc, 1, zeros, one,
            (*iLBCdec_inst).last_lag, iLBCdec_inst);
        memcpy(decresidual, PLCresidual,
            iLBCdec_inst->blockl*sizeof(float));

        order_plus_one = LPC_FILTERORDER + 1;
        for (i = 0; i < iLBCdec_inst->nsub; i++) {
            memcpy(syntdenum+(i*order_plus_one), PLClpc,
                order_plus_one*sizeof(float));
        }
    }

    if (iLBCdec_inst->use_enhancer == 1) {

        /* ポストフィルター処理 */

        iLBCdec_inst->last_lag =
            enhancerInterface(data, decresidual, iLBCdec_inst);

        /* 合成フィルター処理 */

        if (iLBCdec_inst->mode==20) {
            /* エンハンサーには40サンプルの遅延がある */
            i=0;
            syntFilter(data + i*SUBL,
                iLBCdec_inst->old_syntdenum +
                (i+iLBCdec_inst->nsub-1)*(LPC_FILTERORDER+1),
                SUBL, iLBCdec_inst->syntMem);
            for (i=1; i < iLBCdec_inst->nsub; i++) {
                syntFilter(data + i*SUBL,
                    syntdenum + (i-1)*(LPC_FILTERORDER+1),
                    SUBL, iLBCdec_inst->syntMem);
            }
        } else if (iLBCdec_inst->mode==30) {
            /* エンハンサーには80サンプルの遅延がある */
            for (i=0; i < 2; i++) {
                syntFilter(data + i*SUBL,
                    iLBCdec_inst->old_syntdenum +
                    (i+iLBCdec_inst->nsub-2)*(LPC_FILTERORDER+1),
                    SUBL, iLBCdec_inst->syntMem);
            }
            for (i=2; i < iLBCdec_inst->nsub; i++) {
                syntFilter(data + i*SUBL,
                    syntdenum + (i-2)*(LPC_FILTERORDER+1), SUBL,
                    iLBCdec_inst->syntMem);
            }
        }

    } else {

        /* 最後のラグを探す */
        lag = 20;
        maxcc = xCorrCoef(&decresidual[BLOCKL_MAX-ENH_BLOCKL],
            &decresidual[BLOCKL_MAX-ENH_BLOCKL-lag], ENH_BLOCKL);

        for (ilag=21; ilag<120; ilag++) {
            cc = xCorrCoef(&decresidual[BLOCKL_MAX-ENH_BLOCKL],
                &decresidual[BLOCKL_MAX-ENH_BLOCKL-ilag],
                ENH_BLOCKL);

            if (cc > maxcc) {
                maxcc = cc;
                lag = ilag;
            }
        }
        iLBCdec_inst->last_lag = lag;

        /* データをコピーして合成フィルターを実行 */

        memcpy(data, decresidual,
            iLBCdec_inst->blockl*sizeof(float));
        for (i=0; i < iLBCdec_inst->nsub; i++) {
            syntFilter(data + i*SUBL,
                syntdenum + i*(LPC_FILTERORDER+1), SUBL,
                iLBCdec_inst->syntMem);
        }
    }

    /* 必要であれば出力にハイパスフィルター処理を行い、
       そうでなければ出力にコピー */

    hpOutput(data, iLBCdec_inst->blockl,
                decblock,iLBCdec_inst->hpomem);

    /* memcpy(decblock,data,iLBCdec_inst->blockl*sizeof(float));*/

    memcpy(iLBCdec_inst->old_syntdenum, syntdenum,

        iLBCdec_inst->nsub*(LPC_FILTERORDER+1)*sizeof(float));

    iLBCdec_inst->prev_enh_pl=0;

    if (mode==0) { /* PLCを使用した */
        iLBCdec_inst->prev_enh_pl=1;
    }
}

