/*----------------------------------------------------------------*
 *  LP分析フィルター
 *---------------------------------------------------------------*/

void anaFilter(
    float *In,  /* (i) フィルター処理する信号 */
    float *a,   /* (i) LPパラメーター */
    int len,/* (i) 信号の長さ */
    float *Out, /* (o) フィルター処理した信号 */
    float *mem  /* (i/o) フィルター状態 */
){
    int i, j;
    float *po, *pi, *pm, *pa;

    po = Out;

    /* 過去のメモリーを使って前半部分をフィルター処理 */

    for (i=0; i<LPC_FILTERORDER; i++) {
        pi = &In[i];
        pm = &mem[LPC_FILTERORDER-1];
        pa = a;
        *po=0.0;
        for (j=0; j<=i; j++) {
            *po+=(*pa++)*(*pi--);
        }
        for (j=i+1; j<LPC_FILTERORDER+1; j++) {

            *po+=(*pa++)*(*pm--);
        }
        po++;
    }

    /* 状態がすべて入力ベクトル内にある後半部分を
       フィルター処理 */

    for (i=LPC_FILTERORDER; i<len; i++) {
        pi = &In[i];
        pa = a;
        *po=0.0;
        for (j=0; j<LPC_FILTERORDER+1; j++) {
            *po+=(*pa++)*(*pi--);
        }
        po++;
    }

    /* 状態ベクトルを更新 */

    memcpy(mem, &In[len-LPC_FILTERORDER],
        LPC_FILTERORDER*sizeof(float));
}

