void searchAugmentedCB( int low, /* (i) 探索の開始インデックス */ int high, /* (i) 探索の終了インデックス */ int stage, /* (i) 現在のステージ */ int startIndex, /* (i) 最初の増強ベクトルの CBインデックス */ float *target, /* (i) 符号化するターゲットベクトル */ float *buffer, /* (i) 増強コードブック構築用の バッファーの末尾への ポインター */ float *max_measure, /* (i/o) 現時点の最大尺度 */ int *best_index,/* (o) 現時点の最良インデックス */ float *gain, /* (o) 現時点の最良ゲイン */ float *energy, /* (o) 増強コードブック ベクトルのエネルギー */ float *invenergy/* (o) 増強コードブックベクトルの エネルギーの逆数 */ );
void createAugmentedVec( int index, /* (i) 作成する増強ベクトルの インデックス */ float *buffer, /* (i) 増強コードブック構築用の バッファーの末尾への ポインター */ float *cbVec /* (o) 構築したコードブックベクトル */ );
