#include "iLBC_define.h"
#include "constants.h"
#include <string.h>
#include <math.h>

/*----------------------------------------------------------------*
 *  初期コードブックバッファーをフィルター処理して、追加の
 *  コードブックベクトルを構築します。このベクトルは、コード
 *  ブックに追加のセクションを加えて拡張するために使います。
 *---------------------------------------------------------------*/

void filteredCBvecs(
    float *cbvectors,   /* (o) 上位セクションの
                               コードブックベクトル */
    float *mem,         /* (i) コードブックベクトルの
                               作成元のバッファー */
    int lMem        /* (i) バッファーの長さ */
){
    int j, k;
    float *pp, *pp1;
    float tempbuff2[CB_MEML+CB_FILTERLEN];
    float *pos;

    memset(tempbuff2, 0, (CB_HALFFILTERLEN-1)*sizeof(float));
    memcpy(&tempbuff2[CB_HALFFILTERLEN-1], mem, lMem*sizeof(float));
    memset(&tempbuff2[lMem+CB_HALFFILTERLEN-1], 0,
        (CB_HALFFILTERLEN+1)*sizeof(float));

    /* フィルター処理で上位セクションのコードブックベクトルを作成 */

    /* フィルター処理 */
    pos=cbvectors;
    memset(pos, 0, lMem*sizeof(float));
    for (k=0; k<lMem; k++) {
        pp=&tempbuff2[k];
        pp1=&cbfiltersTbl[CB_FILTERLEN-1];
        for (j=0;j<CB_FILTERLEN;j++) {
            (*pos)+=(*pp++)*(*pp1--);
        }
        pos++;
    }
}

/*----------------------------------------------------------------*
 *  コードブックの増強部分を探索して、最良の尺度を見つけます。
 *
 *----------------------------------------------------------------*/
void searchAugmentedCB(
    int low,        /* (i) 探索の開始インデックス */
    int high,           /* (i) 探索の終了インデックス */
    int stage,          /* (i) 現在のステージ */
    int startIndex,     /* (i) 最初の増強ベクトルの
                               コードブックインデックス */
    float *target,      /* (i) 符号化するターゲットベクトル */
    float *buffer,      /* (i) 増強コードブック構築用の
                               バッファーの末尾へのポインター */
    float *max_measure, /* (i/o) 現時点の最大尺度 */
    int *best_index,/* (o) 現時点の最良インデックス */
    float *gain,    /* (o) 現時点の最良ゲイン */
    float *energy,      /* (o) 増強コードブックベクトルの
                               エネルギー */
    float *invenergy/* (o) 増強コードブックベクトルの
                               エネルギーの逆数 */
) {
    int icount, ilow, j, tmpIndex;
    float *pp, *ppo, *ppi, *ppe, crossDot, alfa;
    float weighted, measure, nrjRecursive;
    float ftmp;

    /* 補間しない最初の(low-5)サンプルの
       エネルギーを計算 */
    nrjRecursive = (float) 0.0;
    pp = buffer - low + 1;
    for (j=0; j<(low-5); j++) {
        nrjRecursive += ( (*pp)*(*pp) );
        pp++;
    }
    ppe = buffer - low;


    for (icount=low; icount<=high; icount++) {

        /* エネルギー値の取得に使うコードブック
           ベクトルのインデックス */
        tmpIndex = startIndex+icount-20;

        ilow = icount-4;

        /* 計算量を減らすためにエネルギーを再帰的に更新 */
        nrjRecursive = nrjRecursive + (*ppe)*(*ppe);
        ppe--;
        energy[tmpIndex] = nrjRecursive;

        /* 最初の(low-5)サンプルについて相互内積を
           計算 */
        crossDot = (float) 0.0;
        pp = buffer-icount;
        for (j=0; j<ilow; j++) {
            crossDot += target[j]*(*pp++);
        }

        /* 補間 */
        alfa = (float) 0.2;
        ppo = buffer-4;
        ppi = buffer-icount-4;
        for (j=ilow; j<icount; j++) {
            weighted = ((float)1.0-alfa)*(*ppo)+alfa*(*ppi);
            ppo++;
            ppi++;
            energy[tmpIndex] += weighted*weighted;
            crossDot += target[j]*weighted;
            alfa += (float)0.2;
        }

        /* 残りのサンプルについてエネルギーと相互内積を
           計算 */
        pp = buffer - icount;
        for (j=icount; j<SUBL; j++) {
            energy[tmpIndex] += (*pp)*(*pp);
            crossDot += target[j]*(*pp++);
        }

        if (energy[tmpIndex]>0.0) {
            invenergy[tmpIndex]=(float)1.0/(energy[tmpIndex]+EPS);
        } else {
            invenergy[tmpIndex] = (float) 0.0;
        }

        if (stage==0) {
            measure = (float)-10000000.0;

            if (crossDot > 0.0) {
                measure = crossDot*crossDot*invenergy[tmpIndex];
            }
        }
        else {
            measure = crossDot*crossDot*invenergy[tmpIndex];
        }

        /* 尺度がより良いかを確認 */
        ftmp = crossDot*invenergy[tmpIndex];

        if ((measure>*max_measure) && (fabs(ftmp)<CB_MAXGAIN)) {
            *best_index = tmpIndex;
            *max_measure = measure;
            *gain = ftmp;
        }
    }
}


/*----------------------------------------------------------------*
 *  増強部分から特定のコードブックベクトルを再作成します。
 *
 *----------------------------------------------------------------*/

void createAugmentedVec(
    int index,      /* (i) 作成する増強ベクトルの
                           インデックス */
    float *buffer,  /* (i) 増強コードブック構築用の
                           バッファーの末尾へのポインター */
    float *cbVec/* (o) 構築したコードブックベクトル */
) {
    int ilow, j;
    float *pp, *ppo, *ppi, alfa, alfa1, weighted;

    ilow = index-5;

    /* 補間しない最初の部分をコピー */

    pp = buffer-index;
    memcpy(cbVec,pp,sizeof(float)*index);

    /* 補間 */

    alfa1 = (float)0.2;
    alfa = 0.0;
    ppo = buffer-5;
    ppi = buffer-index-5;
    for (j=ilow; j<index; j++) {
        weighted = ((float)1.0-alfa)*(*ppo)+alfa*(*ppi);
        ppo++;
        ppi++;
        cbVec[j] = weighted;
        alfa += alfa1;
    }

    /* 補間しない2番目の部分をコピー */

    pp = buffer - index;
    memcpy(cbVec+index,pp,sizeof(float)*(SUBL-index));
}

