#include <math.h>
#include <string.h>
#include <stdio.h>
#include "iLBC_define.h"

/*----------------------------------------------------------------*
 *  指定したラグにおける最後のサブフレームのピッチ予測について、
 *  相互相関とピッチゲインを計算します。
 *---------------------------------------------------------------*/

void compCorr(
    float *cc,      /* (o) 相互相関係数 */
    float *gc,      /* (o) ゲイン */
    float *pm,
    float *buffer,  /* (i) 信号バッファー */
    int lag,    /* (i) ピッチラグ */
    int bLen,       /* (i) バッファーの長さ */
    int sRange      /* (i) 相関の探索長 */
){
    int i;
    float ftmp1, ftmp2, ftmp3;

    /* バッファーの外に出ないようにする */
    if ((bLen-sRange-lag)<0) {
        sRange=bLen-lag;
    }

    ftmp1 = 0.0;
    ftmp2 = 0.0;
    ftmp3 = 0.0;
    for (i=0; i<sRange; i++) {
        ftmp1 += buffer[bLen-sRange+i] *
            buffer[bLen-sRange+i-lag];
        ftmp2 += buffer[bLen-sRange+i-lag] *
                buffer[bLen-sRange+i-lag];
        ftmp3 += buffer[bLen-sRange+i] *
                buffer[bLen-sRange+i];
    }

    if (ftmp2 > 0.0) {
        *cc = ftmp1*ftmp1/ftmp2;
        *gc = (float)fabs(ftmp1/ftmp2);
        *pm=(float)fabs(ftmp1)/
            ((float)sqrt(ftmp2)*(float)sqrt(ftmp3));
    }
    else {
        *cc = 0.0;
        *gc = 0.0;
        *pm=0.0;
    }
}
/*----------------------------------------------------------------*
 *  パケットロス隠蔽ルーチン。残差信号とLPパラメーターを隠蔽
 *  します。パケットロスがなければ状態を更新します。
 *---------------------------------------------------------------*/

void doThePLC(
    float *PLCresidual, /* (o) 隠蔽した残差 */
    float *PLClpc,      /* (o) 隠蔽したLPパラメーター */
    int PLI,        /* (i) パケットロス指示子
                               0 - PLなし、1 = PLあり */
    float *decresidual, /* (i) 復号した残差 */
    float *lpc,         /* (i) 復号したLPC（PLなしのときのみ使用） */
    int inlag,          /* (i) ピッチラグ */
    iLBC_Dec_Inst_t *iLBCdec_inst
                        /* (i/o) デコーダーインスタンス */
){
    int lag=20, randlag;
    float gain, maxcc;
    float use_gain;
    float gain_comp, maxcc_comp, per, max_per;
    int i, pick, use_lag;
    float ftmp, randvec[BLOCKL_MAX], pitchfact, energy;

    /* パケットロス */

    if (PLI == 1) {

        iLBCdec_inst->consPLICount += 1;

        /* 前のフレームが失われていなければ、
           ピッチ予測ゲインを決定する */

        if (iLBCdec_inst->prevPLI != 1) {

            /* 前のラグの周辺を探索して、
               最適なピッチ周期を見つける */

            lag=inlag-3;
            compCorr(&maxcc, &gain, &max_per,
                iLBCdec_inst->prevResidual,
                lag, iLBCdec_inst->blockl, 60);
            for (i=inlag-2;i<=inlag+3;i++) {
                compCorr(&maxcc_comp, &gain_comp, &per,
                    iLBCdec_inst->prevResidual,
                    i, iLBCdec_inst->blockl, 60);

                if (maxcc_comp>maxcc) {
                    maxcc=maxcc_comp;
                    gain=gain_comp;
                    lag=i;
                    max_per=per;
                }
            }

        }

        /* 前のフレームが失われていたら、記録したラグと周期性を使う */

        else {
            lag=iLBCdec_inst->prevLag;
            max_per=iLBCdec_inst->per;
        }

        /* 減衰 */

        use_gain=1.0;
        if (iLBCdec_inst->consPLICount*iLBCdec_inst->blockl>320)
            use_gain=(float)0.9;
        else if (iLBCdec_inst->consPLICount*
                        iLBCdec_inst->blockl>2*320)
            use_gain=(float)0.7;
        else if (iLBCdec_inst->consPLICount*
                        iLBCdec_inst->blockl>3*320)
            use_gain=(float)0.5;
        else if (iLBCdec_inst->consPLICount*
                        iLBCdec_inst->blockl>4*320)
            use_gain=(float)0.0;

        /* 雑音とピッチの繰り返しを混合 */
        ftmp=(float)sqrt(max_per);
        if (ftmp>(float)0.7)
            pitchfact=(float)1.0;
        else if (ftmp>(float)0.4)
            pitchfact=(ftmp-(float)0.4)/((float)0.7-(float)0.4);
        else
            pitchfact=0.0;


        /* 同じピッチ周期の繰り返しを避ける */
        use_lag=lag;
        if (lag<80) {
            use_lag=2*lag;
        }

        /* 隠蔽した残差を計算 */
        energy = 0.0;
        for (i=0; i<iLBCdec_inst->blockl; i++) {

            /* 雑音成分 */

            iLBCdec_inst->seed=(iLBCdec_inst->seed*69069L+1) &
                (0x80000000L-1);
            randlag = 50 + ((signed long) iLBCdec_inst->seed)%70;
            pick = i - randlag;

            if (pick < 0) {
                randvec[i] =
                    iLBCdec_inst->prevResidual[
                                iLBCdec_inst->blockl+pick];
            } else {
                randvec[i] =  randvec[pick];
            }

            /* ピッチの繰り返し成分 */
            pick = i - use_lag;

            if (pick < 0) {
                PLCresidual[i] =
                    iLBCdec_inst->prevResidual[
                                iLBCdec_inst->blockl+pick];
            } else {
                PLCresidual[i] = PLCresidual[pick];
            }

            /* ランダム成分と周期成分を混合 */

            if (i<80)
                PLCresidual[i] = use_gain*(pitchfact *
                            PLCresidual[i] +
                            ((float)1.0 - pitchfact) * randvec[i]);
            else if (i<160)
                PLCresidual[i] = (float)0.95*use_gain*(pitchfact *
                            PLCresidual[i] +
                            ((float)1.0 - pitchfact) * randvec[i]);
            else
                PLCresidual[i] = (float)0.9*use_gain*(pitchfact *
                            PLCresidual[i] +
                            ((float)1.0 - pitchfact) * randvec[i]);

            energy += PLCresidual[i] * PLCresidual[i];
        }

        /* 30dB未満なら雑音のみを使う */
        if (sqrt(energy/(float)iLBCdec_inst->blockl) < 30.0) {
            gain=0.0;
            for (i=0; i<iLBCdec_inst->blockl; i++) {
                PLCresidual[i] = randvec[i];
            }
        }

        /* 古いLPCを使う */

        memcpy(PLClpc,iLBCdec_inst->prevLpc,
            (LPC_FILTERORDER+1)*sizeof(float));

    }

    /* パケットロスなし、入力をコピー */

    else {
        memcpy(PLCresidual, decresidual,
            iLBCdec_inst->blockl*sizeof(float));
        memcpy(PLClpc, lpc, (LPC_FILTERORDER+1)*sizeof(float));
        iLBCdec_inst->consPLICount = 0;
    }

    /* 状態を更新 */

    if (PLI) {
        iLBCdec_inst->prevLag = lag;
        iLBCdec_inst->per=max_per;
    }

    iLBCdec_inst->prevPLI = PLI;
    memcpy(iLBCdec_inst->prevLpc, PLClpc,
        (LPC_FILTERORDER+1)*sizeof(float));
    memcpy(iLBCdec_inst->prevResidual, PLCresidual,
        iLBCdec_inst->blockl*sizeof(float));
}

