/*----------------------------------------------------------------*
 * 二乗誤差基準で「value」にもっとも近い配列要素を探し、
 * そのインデックスを求めます
 *---------------------------------------------------------------*/

void NearestNeighbor(
    int   *index,   /* (o) valueにもっとも近い配列要素の
                           インデックス */
    float *array,   /* (i) データ配列 */
    float value,/* (i) 値 */
    int arlength/* (i) データ配列の次元 */
){
    int i;
    float bestcrit,crit;

    crit=array[0]-value;
    bestcrit=crit*crit;
    *index=0;
    for (i=1; i<arlength; i++) {
        crit=array[i]-value;
        crit=crit*crit;

        if (crit<bestcrit) {
            bestcrit=crit;
            *index=i;
        }
    }
}

/*----------------------------------------------------------------*
 * 系列間の相互相関を計算
 *---------------------------------------------------------------*/

void mycorr1(
    float* corr,    /* (o) seq1とseq2の相関 */
    float* seq1,    /* (i) 1つ目の系列 */
    int dim1,           /* (i) 1つ目の系列seq1の次元 */
    const float *seq2,  /* (i) 2つ目の系列 */
    int dim2        /* (i) seq2の次元 */
){
    int i,j;

    for (i=0; i<=dim1-dim2; i++) {
        corr[i]=0.0;
        for (j=0; j<dim2; j++) {
            corr[i] += seq1[i+j] * seq2[j];
        }
    }
}

/*----------------------------------------------------------------*
 * 範囲外をゼロとみなして有限長の配列をアップサンプリング
 *---------------------------------------------------------------*/
void enh_upsample(
    float* useq1,   /* (o) アップサンプリングした出力系列 */
    float* seq1,/* (i) アップサンプリング前の系列 */
    int dim1,       /* (i) seq1の次元 */
    int hfl         /* (i) ポリフェーズフィルターの長さ=2*hfl+1 */
){
    float *pu,*ps;
    int i,j,k,q,filterlength,hfl2;
    const float *polyp[ENH_UPS0]; /* ポリフェーズの列への
                                     ポインター */
    const float *pp;

    /* フィルター用のポインターを定義 */

    filterlength=2*hfl+1;

    if ( filterlength > dim1 ) {
        hfl2=(int) (dim1/2);
        for (j=0; j<ENH_UPS0; j++) {
            polyp[j]=polyphaserTbl+j*filterlength+hfl-hfl2;
        }
        hfl=hfl2;
        filterlength=2*hfl+1;
    }
    else {
        for (j=0; j<ENH_UPS0; j++) {
            polyp[j]=polyphaserTbl+j*filterlength;
        }
    }

    /* フィルター処理: フィルターが系列の左側にはみ出す部分 */

    pu=useq1;
    for (i=hfl; i<filterlength; i++) {
        for (j=0; j<ENH_UPS0; j++) {
            *pu=0.0;
            pp = polyp[j];
            ps = seq1+i;
            for (k=0; k<=i; k++) {
                *pu += *ps-- * *pp++;
            }
            pu++;
        }
    }

    /* フィルター処理: 単純な畳み込み=内積 */

    for (i=filterlength; i<dim1; i++) {
        for (j=0;j<ENH_UPS0; j++){
            *pu=0.0;
            pp = polyp[j];
            ps = seq1+i;
            for (k=0; k<filterlength; k++) {
                *pu += *ps-- * *pp++;
            }
            pu++;
        }
    }

    /* フィルター処理: フィルターが系列の右側にはみ出す部分 */

    for (q=1; q<=hfl; q++) {
        for (j=0; j<ENH_UPS0; j++) {
            *pu=0.0;
            pp = polyp[j]+q;
            ps = seq1+dim1-1;
            for (k=0; k<filterlength-q; k++) {
                *pu += *ps-- * *pp++;
            }
            pu++;
        }
    }
}


/*----------------------------------------------------------------*
 * idata+estSegPosの付近から始まるセグメントのうち、
 * idata+centerStartPosからidata+centerStartPos+ENH_BLOCKL-1
 * までのセグメントとの相関がもっとも高いものを探します。
 * セグメントは元のサンプリングレートのENH_UPSO倍の分解能で
 * 見つけます
 *---------------------------------------------------------------*/

void refiner(
    float *seg,         /* (o) セグメント配列 */
    float *updStartPos, /* (o) 更新した開始点 */
    float* idata,       /* (i) 元のデータバッファー */
    int idatal,         /* (i) idataの次元 */
    int centerStartPos, /* (i) 中心セグメントの開始位置 */
    float estSegPos,/* (i) 推定した他方のセグメントの開始位置 */
    float period    /* (i) 推定したピッチ周期 */
){
    int estSegPosRounded,searchSegStartPos,searchSegEndPos,corrdim;
    int tloc,tloc2,i,st,en,fraction;
    float vect[ENH_VECTL],corrVec[ENH_CORRDIM],maxv;
    float corrVecUps[ENH_CORRDIM*ENH_UPS0];
    /* 配列の範囲を定義 */

    estSegPosRounded=(int)(estSegPos - 0.5);

    searchSegStartPos=estSegPosRounded-ENH_SLOP;

    if (searchSegStartPos<0) {
        searchSegStartPos=0;
    }
    searchSegEndPos=estSegPosRounded+ENH_SLOP;

    if (searchSegEndPos+ENH_BLOCKL >= idatal) {
        searchSegEndPos=idatal-ENH_BLOCKL-1;
    }
    corrdim=searchSegEndPos-searchSegStartPos+1;

    /* アップサンプリングした相関（corr33）を計算し、
       最大値の位置を見つける */

    mycorr1(corrVec,idata+searchSegStartPos,
        corrdim+ENH_BLOCKL-1,idata+centerStartPos,ENH_BLOCKL);
    enh_upsample(corrVecUps,corrVec,corrdim,ENH_FL0);
    tloc=0; maxv=corrVecUps[0];
    for (i=1; i<ENH_UPS0*corrdim; i++) {

        if (corrVecUps[i]>maxv) {
            tloc=i;
            maxv=corrVecUps[i];
        }
    }

    /* 範囲外に出ることなくアップサンプリングできる
       ベクトルを作る */

    *updStartPos= (float)searchSegStartPos +
        (float)tloc/(float)ENH_UPS0+(float)1.0;
    tloc2=(int)(tloc/ENH_UPS0);

    if (tloc>tloc2*ENH_UPS0) {
        tloc2++;
    }
    st=searchSegStartPos+tloc2-ENH_FL0;

    if (st<0) {
        memset(vect,0,-st*sizeof(float));
        memcpy(&vect[-st],idata, (ENH_VECTL+st)*sizeof(float));
    }
    else {
        en=st+ENH_VECTL;

        if (en>idatal) {
            memcpy(vect, &idata[st],
                (ENH_VECTL-(en-idatal))*sizeof(float));
            memset(&vect[ENH_VECTL-(en-idatal)], 0,
                (en-idatal)*sizeof(float));
        }
        else {
            memcpy(vect, &idata[st], ENH_VECTL*sizeof(float));
        }
    }
    fraction=tloc2*ENH_UPS0-tloc;

    /* セグメントを計算（実際には畳み込み） */

    mycorr1(seg,vect,ENH_VECTL,polyphaserTbl+(2*ENH_FL0+1)*fraction,
        2*ENH_FL0+1);
}

/*----------------------------------------------------------------*
 * 平滑化した出力データを求める
 *---------------------------------------------------------------*/

void smath(
    float *odata,   /* (o) 平滑化した出力 */
    float *sseq,/* (i) 前述の波形の第2系列 */
    int hl,         /* (i) 2*hl+1がsseqの次元 */
    float alpha0/* (i) 平滑化エネルギーの最大比率 */
){
    int i,k;
    float w00,w10,w11,A,B,C,*psseq,err,errs;
    float surround[BLOCKL_MAX]; /* 現在の波形以外が寄与する
                                   形状 */
    float wt[2*ENH_HL+1];       /* 周囲の形状を得るための
                                   波形の重み付け */
    float denom;

    /* 現在の波形を除くすべての波形からの寄与の形状を
       作る */

    for (i=1; i<=2*hl+1; i++) {
        wt[i-1] = (float)0.5*(1 - (float)cos(2*PI*i/(2*hl+2)));
    }
    wt[hl]=0.0; /* 明確化のため。使われない */
    for (i=0; i<ENH_BLOCKL; i++) {
        surround[i]=sseq[i]*wt[0];
    }
    for (k=1; k<hl; k++) {
        psseq=sseq+k*ENH_BLOCKL;
        for(i=0;i<ENH_BLOCKL; i++) {
            surround[i]+=psseq[i]*wt[k];
        }
    }
    for (k=hl+1; k<=2*hl; k++) {
        psseq=sseq+k*ENH_BLOCKL;
        for(i=0;i<ENH_BLOCKL; i++) {
            surround[i]+=psseq[i]*wt[k];
        }
    }

    /* いくつかの内積を計算 */

    w00 = w10 = w11 = 0.0;
    psseq=sseq+hl*ENH_BLOCKL; /* 現在のブロック */
    for (i=0; i<ENH_BLOCKL;i++) {
        w00+=psseq[i]*psseq[i];
        w11+=surround[i]*surround[i];
        w10+=surround[i]*psseq[i];
    }

    if (fabs(w11) < 1.0) {
        w11=1.0;
    }
    C = (float)sqrt( w00/w11);

    /* まずパワー制約なしで強調を試みる */

    errs=0.0;
    psseq=sseq+hl*ENH_BLOCKL;
    for (i=0; i<ENH_BLOCKL; i++) {
        odata[i]=C*surround[i];
        err=psseq[i]-odata[i];
        errs+=err*err;
    }

    /* 最初の試行で制約に違反したら、制約を加える */

    if (errs > alpha0 * w00) {
        if ( w00 < 1) {
            w00=1;
        }
        denom = (w11*w00-w10*w10)/(w00*w00);

        if (denom > 0.0001) { /* 平滑な場合の数値的な問題を
                                 取り除く */
            A = (float)sqrt( (alpha0- alpha0*alpha0/4)/denom);
            B = -alpha0/2 - A * w10/w00;
            B = B+1;
        }
        else { /* 周期間に本質的な差がないため、
                  平滑化は不要 */
            A= 0.0;
            B= 1.0;
        }

        /* 平滑化した系列を作る */

        psseq=sseq+hl*ENH_BLOCKL;
        for (i=0; i<ENH_BLOCKL; i++) {
            odata[i]=A*surround[i]+B*psseq[i];
        }
    }
}

/*----------------------------------------------------------------*
 * ピッチ同期したサンプル系列を得る
 *---------------------------------------------------------------*/

void getsseq(
    float *sseq,    /* (o) ピッチ同期系列 */
    float *idata,       /* (i) 元のデータ */
    int idatal,         /* (i) データの次元 */
    int centerStartPos, /* (i) 現在のブロックの開始位置 */
    float *period,      /* (i) 大まかなピッチ周期の配列 */
    float *plocs,       /* (i) 周期配列の周期を取得した
                               位置 */
    int periodl,    /* (i) 周期配列の次元 */
    int hl              /* (i) 2*hl+1が系列の数 */
){
    int i,centerEndPos,q;
    float blockStartPos[2*ENH_HL+1];
    int lagBlock[2*ENH_HL+1];
    float plocs2[ENH_PLOCSL];
    float *psseq;

    centerEndPos=centerStartPos+ENH_BLOCKL-1;

    /* 現在 */

    NearestNeighbor(lagBlock+hl,plocs,
        (float)0.5*(centerStartPos+centerEndPos),periodl);

    blockStartPos[hl]=(float)centerStartPos;
    psseq=sseq+ENH_BLOCKL*hl;
    memcpy(psseq, idata+centerStartPos, ENH_BLOCKL*sizeof(float));

    /* 過去 */

    for (q=hl-1; q>=0; q--) {
        blockStartPos[q]=blockStartPos[q+1]-period[lagBlock[q+1]];
        NearestNeighbor(lagBlock+q,plocs,
            blockStartPos[q]+
            ENH_BLOCKL_HALF-period[lagBlock[q+1]], periodl);


        if (blockStartPos[q]-ENH_OVERHANG>=0) {
            refiner(sseq+q*ENH_BLOCKL, blockStartPos+q, idata,
                idatal, centerStartPos, blockStartPos[q],
                period[lagBlock[q+1]]);
        } else {
            psseq=sseq+q*ENH_BLOCKL;
            memset(psseq, 0, ENH_BLOCKL*sizeof(float));
        }
    }

    /* 未来 */

    for (i=0; i<periodl; i++) {
        plocs2[i]=plocs[i]-period[i];
    }
    for (q=hl+1; q<=2*hl; q++) {
        NearestNeighbor(lagBlock+q,plocs2,
            blockStartPos[q-1]+ENH_BLOCKL_HALF,periodl);

        blockStartPos[q]=blockStartPos[q-1]+period[lagBlock[q]];
        if (blockStartPos[q]+ENH_BLOCKL+ENH_OVERHANG<idatal) {
            refiner(sseq+ENH_BLOCKL*q, blockStartPos+q, idata,
                idatal, centerStartPos, blockStartPos[q],
                period[lagBlock[q]]);
        }
        else {
            psseq=sseq+q*ENH_BLOCKL;
            memset(psseq, 0, ENH_BLOCKL*sizeof(float));
        }
    }
}

/*----------------------------------------------------------------*
 * idata+centerStartPosからidata+centerStartPos+ENH_BLOCKL-1
 * までを強調する
 *---------------------------------------------------------------*/
void enhancer(
    float *odata,       /* (o) 平滑化したブロック。次元はblockl */
    float *idata,       /* (i) 強調に使うデータバッファー */
    int idatal,         /* (i) idataの次元 */
    int centerStartPos, /* (i) idata内の現在のブロックの
                               最初のサンプル */
    float alpha0,       /* (i) 補正エネルギーの最大比率
                              （[0,1]の範囲） */
    float *period,      /* (i) ピッチ周期の配列 */
    float *plocs,       /* (i) 周期配列の値が有効な
                               位置 */
    int periodl         /* (i) periodとplocsの次元 */
){
    float sseq[(2*ENH_HL+1)*ENH_BLOCKL];

    /* 前述のセグメントの第2系列を得る */

    getsseq(sseq,idata,idatal,centerStartPos,period,
        plocs,periodl,ENH_HL);

    /* 前述の第2系列から平滑化した出力を計算 */

    smath(odata,sseq,ENH_HL,alpha0);

}

/*----------------------------------------------------------------*
 * 相互相関
 *---------------------------------------------------------------*/

float xCorrCoef(
    float *target,      /* (i) 1つ目の配列 */
    float *regressor,   /* (i) 2つ目の配列 */
    int subl        /* (i) 配列の次元 */
){
    int i;
    float ftmp1, ftmp2;

    ftmp1 = 0.0;
    ftmp2 = 0.0;
    for (i=0; i<subl; i++) {
        ftmp1 += target[i]*regressor[i];
        ftmp2 += regressor[i]*regressor[i];
    }

    if (ftmp1 > 0.0) {
        return (float)(ftmp1*ftmp1/ftmp2);
    }
    else {
        return (float)0.0;
    }
}

/*----------------------------------------------------------------*
 * エンハンサーのインターフェース
 *---------------------------------------------------------------*/

int enhancerInterface(
    float *out,                     /* (o) 強調した信号 */
    float *in,                      /* (i) 強調前の信号 */
    iLBC_Dec_Inst_t *iLBCdec_inst   /* (i) バッファーなど */
){
    float *enh_buf, *enh_period;
    int iblock, isample;
    int lag=0, ilag, i, ioffset;
    float cc, maxcc;
    float ftmp1, ftmp2;
    float *inPtr, *enh_bufPtr1, *enh_bufPtr2;
    float plc_pred[ENH_BLOCKL];

    float lpState[6], downsampled[(ENH_NBLOCKS*ENH_BLOCKL+120)/2];
    int inLen=ENH_NBLOCKS*ENH_BLOCKL+120;
    int start, plc_blockl, inlag;

    enh_buf=iLBCdec_inst->enh_buf;
    enh_period=iLBCdec_inst->enh_period;

    memmove(enh_buf, &enh_buf[iLBCdec_inst->blockl],
        (ENH_BUFL-iLBCdec_inst->blockl)*sizeof(float));

    memcpy(&enh_buf[ENH_BUFL-iLBCdec_inst->blockl], in,
        iLBCdec_inst->blockl*sizeof(float));

    if (iLBCdec_inst->mode==30)
        plc_blockl=ENH_BLOCKL;
    else
        plc_blockl=40;

    /* 20msフレームのときは処理を1ブロックずらす */
    ioffset=0;
    if (iLBCdec_inst->mode==20) ioffset=1;

    i=3-ioffset;
    memmove(enh_period, &enh_period[i],
        (ENH_NBLOCKS_TOT-i)*sizeof(float));
    /* 状態情報を、ダウンサンプリングするサンプルの直前の
       6サンプルに設定する。 */

    memcpy(lpState,
        enh_buf+(ENH_NBLOCKS_EXTRA+ioffset)*ENH_BLOCKL-126,
        6*sizeof(float));

    /* 計算量を節約するため1/2にダウンサンプリング */

    DownSample(enh_buf+(ENH_NBLOCKS_EXTRA+ioffset)*ENH_BLOCKL-120,
                lpFilt_coefsTbl, inLen-ioffset*ENH_BLOCKL,
                lpState, downsampled);

    /* ダウンサンプリングした領域でピッチを推定する。 */
    for (iblock = 0; iblock<ENH_NBLOCKS-ioffset; iblock++) {

        lag = 10;
        maxcc = xCorrCoef(downsampled+60+iblock*
            ENH_BLOCKL_HALF, downsampled+60+iblock*
            ENH_BLOCKL_HALF-lag, ENH_BLOCKL_HALF);
        for (ilag=11; ilag<60; ilag++) {
            cc = xCorrCoef(downsampled+60+iblock*
                ENH_BLOCKL_HALF, downsampled+60+iblock*
                ENH_BLOCKL_HALF-ilag, ENH_BLOCKL_HALF);

            if (cc > maxcc) {
                maxcc = cc;
                lag = ilag;
            }
        }

        /* 推定したラグをダウンサンプリング前の領域で保存 */
        enh_period[iblock+ENH_NBLOCKS_EXTRA+ioffset] = (float)lag*2;


    }


    /* 前のパケットでPLCを実行した */
    if (iLBCdec_inst->prev_enh_pl==1) {

        inlag=(int)enh_period[ENH_NBLOCKS_EXTRA+ioffset];

        lag = inlag-1;
        maxcc = xCorrCoef(in, in+lag, plc_blockl);
        for (ilag=inlag; ilag<=inlag+1; ilag++) {
            cc = xCorrCoef(in, in+ilag, plc_blockl);
            if (cc > maxcc) {
                maxcc = cc;
                lag = ilag;
            }
        }

        enh_period[ENH_NBLOCKS_EXTRA+ioffset-1]=(float)lag;

        /* 古い先読み部分について新たに隠蔽した残差を計算し、
           前方向のPLCと新しいフレームからの後ろ向きの
           PLCを混合する */

        inPtr=&in[lag-1];

        enh_bufPtr1=&plc_pred[plc_blockl-1];

        if (lag>plc_blockl) {
            start=plc_blockl;
        } else {
            start=lag;
        }

        for (isample = start; isample>0; isample--) {
            *enh_bufPtr1-- = *inPtr--;
        }

        enh_bufPtr2=&enh_buf[ENH_BUFL-1-iLBCdec_inst->blockl];
        for (isample = (plc_blockl-1-lag); isample>=0; isample--) {
            *enh_bufPtr1-- = *enh_bufPtr2--;
        }

        /* エネルギーの変化を制限 */
        ftmp2=0.0;
        ftmp1=0.0;
        for (i=0;i<plc_blockl;i++) {
            ftmp2+=enh_buf[ENH_BUFL-1-iLBCdec_inst->blockl-i]*
                enh_buf[ENH_BUFL-1-iLBCdec_inst->blockl-i];
            ftmp1+=plc_pred[i]*plc_pred[i];
        }
        ftmp1=(float)sqrt(ftmp1/(float)plc_blockl);
        ftmp2=(float)sqrt(ftmp2/(float)plc_blockl);
        if (ftmp1>(float)2.0*ftmp2 && ftmp1>0.0) {
            for (i=0;i<plc_blockl-10;i++) {
                plc_pred[i]*=(float)2.0*ftmp2/ftmp1;
            }
            for (i=plc_blockl-10;i<plc_blockl;i++) {
                plc_pred[i]*=(float)(i-plc_blockl+10)*
                    ((float)1.0-(float)2.0*ftmp2/ftmp1)/(float)(10)+
                    (float)2.0*ftmp2/ftmp1;
            }
        }

        enh_bufPtr1=&enh_buf[ENH_BUFL-1-iLBCdec_inst->blockl];
        for (i=0; i<plc_blockl; i++) {
            ftmp1 = (float) (i+1) / (float) (plc_blockl+1);
            *enh_bufPtr1 *= ftmp1;
            *enh_bufPtr1 += ((float)1.0-ftmp1)*
                                plc_pred[plc_blockl-1-i];
            enh_bufPtr1--;
        }
    }

    if (iLBCdec_inst->mode==20) {
        /* 40サンプルの遅延を持つエンハンサー */
        for (iblock = 0; iblock<2; iblock++) {
            enhancer(out+iblock*ENH_BLOCKL, enh_buf,
                ENH_BUFL, (5+iblock)*ENH_BLOCKL+40,
                ENH_ALPHA0, enh_period, enh_plocsTbl,
                    ENH_NBLOCKS_TOT);
        }
    } else if (iLBCdec_inst->mode==30) {
        /* 80サンプルの遅延を持つエンハンサー */
        for (iblock = 0; iblock<3; iblock++) {
            enhancer(out+iblock*ENH_BLOCKL, enh_buf,
                ENH_BUFL, (4+iblock)*ENH_BLOCKL,
                ENH_ALPHA0, enh_period, enh_plocsTbl,
                    ENH_NBLOCKS_TOT);
        }
    }

    return (lag*2);
}

