void AllZeroFilter( float *In, /* (i) In[0]からIn[lengthInOut-1]には フィルターの入力サンプルが入る */ float *Coef,/* (i) フィルター係数（Coef[0]は1.0と 仮定する） */ int lengthInOut,/* (i) 入出力サンプル数 */ int orderCoef, /* (i) フィルター係数の数 */ float *Out /* (i/o) 入力時、Out[-orderCoef]からOut[-1] にはフィルター状態が入る。出力時、 Out[0]からOut[lengthInOut-1]には フィルター処理したサンプルが入る */ );
void ZeroPoleFilter( float *In, /* (i) In[0]からIn[lengthInOut-1]には フィルターの入力サンプルが入り、 In[-orderCoef]からIn[-1]には全零 部分の状態が入る */ float *ZeroCoef,/* (i) 全零部分のフィルター係数 （ZeroCoef[0]は1.0と仮定する） */ float *PoleCoef,/* (i) 全極部分のフィルター係数 （ZeroCoef[0]は1.0と仮定する） */ int lengthInOut,/* (i) 入出力サンプル数 */ int orderCoef, /* (i) フィルター係数の数 */ float *Out /* (i/o) 入力時、Out[-orderCoef]からOut[-1] には全極部分の状態が入る。出力時、 Out[0]からOut[lengthInOut-1]には フィルター処理したサンプルが入る */ ); void DownSample ( float *In, /* (i) 入力サンプル */ float *Coef, /* (i) フィルター係数 */ int lengthIn, /* (i) 入力サンプル数 */ float *state, /* (i) フィルター状態 */ float *Out /* (o) ダウンサンプリングした出力 */ );
