#include "iLBC_define.h"

/*----------------------------------------------------------------*
 *  全極フィルター
 *---------------------------------------------------------------*/

void AllPoleFilter(
    float *InOut,   /* (i/o) 入力時、InOut[-orderCoef]から
                           InOut[-1]にはフィルターの状態（遅延
                           サンプル）が入り、InOut[0]から
                           InOut[lengthInOut-1]にはフィルターの
                           入力が入る。出力時、InOut[-orderCoef]
                           からInOut[-1]は変更されず、InOut[0]
                           からInOut[lengthInOut-1]にはフィルター
                           処理したサンプルが入る */
    float *Coef,/* (i) フィルター係数。Coef[0]は1.0と
                           仮定する */
    int lengthInOut,/* (i) 入出力サンプル数 */
    int orderCoef   /* (i) フィルター係数の数 */
){
    int n,k;

    for(n=0;n<lengthInOut;n++){
        for(k=1;k<=orderCoef;k++){
            *InOut -= Coef[k]*InOut[-k];
        }
        InOut++;
    }
}

/*----------------------------------------------------------------*
 *  全零フィルター
 *---------------------------------------------------------------*/

void AllZeroFilter(
    float *In,      /* (i) In[0]からIn[lengthInOut-1]には
                           フィルターの入力サンプルが入る */
    float *Coef,/* (i) フィルター係数（Coef[0]は1.0と
                           仮定する） */
    int lengthInOut,/* (i) 入出力サンプル数 */
    int orderCoef,  /* (i) フィルター係数の数 */
    float *Out      /* (i/o) 入力時、Out[-orderCoef]からOut[-1]
                           にはフィルター状態が入る。出力時、
                           Out[0]からOut[lengthInOut-1]には
                           フィルター処理したサンプルが入る */
){
    int n,k;

    for(n=0;n<lengthInOut;n++){
        *Out = Coef[0]*In[0];
        for(k=1;k<=orderCoef;k++){
            *Out += Coef[k]*In[-k];
        }
        Out++;
        In++;
    }
}

/*----------------------------------------------------------------*
 *  極零フィルター
 *---------------------------------------------------------------*/

void ZeroPoleFilter(
    float *In,      /* (i) In[0]からIn[lengthInOut-1]には
                           フィルターの入力サンプルが入り、
                           In[-orderCoef]からIn[-1]には全零
                           部分の状態が入る */
    float *ZeroCoef,/* (i) 全零部分のフィルター係数
                           （ZeroCoef[0]は1.0と仮定する） */
    float *PoleCoef,/* (i) 全極部分のフィルター係数
                           （ZeroCoef[0]は1.0と仮定する） */
    int lengthInOut,/* (i) 入出力サンプル数 */
    int orderCoef,  /* (i) フィルター係数の数 */
    float *Out      /* (i/o) 入力時、Out[-orderCoef]からOut[-1]
                           には全極部分の状態が入る。出力時、
                           Out[0]からOut[lengthInOut-1]には
                           フィルター処理したサンプルが入る */
){
    AllZeroFilter(In,ZeroCoef,lengthInOut,orderCoef,Out);
    AllPoleFilter(Out,PoleCoef,lengthInOut,orderCoef);
}

/*----------------------------------------------------------------*
 * ダウンサンプリング（LPフィルターと間引き）
 *---------------------------------------------------------------*/

void DownSample (
    float  *In,     /* (i) 入力サンプル */
    float  *Coef,   /* (i) フィルター係数 */
    int lengthIn,   /* (i) 入力サンプル数 */
    float  *state,  /* (i) フィルター状態 */
    float  *Out     /* (o) ダウンサンプリングした出力 */
){
    float   o;
    float *Out_ptr = Out;
    float *Coef_ptr, *In_ptr;
    float *state_ptr;
    int i, j, stop;

    /* LPフィルターと間引きを同時に行う */

    for (i = DELAY_DS; i < lengthIn; i+=FACTOR_DS)
    {
        Coef_ptr = &Coef[0];
        In_ptr = &In[i];
        state_ptr = &state[FILTERORDER_DS-2];

        o = (float)0.0;

        stop = (i < FILTERORDER_DS) ? i + 1 : FILTERORDER_DS;

        for (j = 0; j < stop; j++)
        {
            o += *Coef_ptr++ * (*In_ptr--);
        }
        for (j = i + 1; j < FILTERORDER_DS; j++)
        {
            o += *Coef_ptr++ * (*state_ptr--);
        }
        *Out_ptr++ = o;
    }

    /* 最後の部分を得る（未来の入力としてゼロを使う） */

    for (i=(lengthIn+FACTOR_DS); i<(lengthIn+DELAY_DS);
            i+=FACTOR_DS) {

        o=(float)0.0;

        if (i<lengthIn) {
            Coef_ptr = &Coef[0];
            In_ptr = &In[i];
            for (j=0; j<FILTERORDER_DS; j++) {
                    o += *Coef_ptr++ * (*Out_ptr--);
            }
        } else {
            Coef_ptr = &Coef[i-lengthIn];
            In_ptr = &In[lengthIn-1];
            for (j=0; j<FILTERORDER_DS-(i-lengthIn); j++) {
                    o += *Coef_ptr++ * (*In_ptr--);
            }
        }
        *Out_ptr++ = o;
    }
}

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    FrameClassify.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include "iLBC_define.h"

/*---------------------------------------------------------------*
 *  開始状態の位置を決めるためのサブフレームの分類
 *--------------------------------------------------------------*/

int FrameClassify(      /* 最大エネルギーのサブフレームのインデックス */
    iLBC_Enc_Inst_t *iLBCenc_inst,
                        /* (i/o) エンコーダー状態の構造体 */
    float *residual     /* (i) LPC残差信号 */
) {
    float max_ssqEn, fssqEn[NSUB_MAX], bssqEn[NSUB_MAX], *pp;
    int n, l, max_ssqEn_n;
    const float ssqEn_win[NSUB_MAX-1]={(float)0.8,(float)0.9,
        (float)1.0,(float)0.9,(float)0.8};
    const float sampEn_win[5]={(float)1.0/(float)6.0,
        (float)2.0/(float)6.0, (float)3.0/(float)6.0,
        (float)4.0/(float)6.0, (float)5.0/(float)6.0};

    /* 前方と後方のエネルギーをゼロで初期化 */

    memset(fssqEn, 0, NSUB_MAX*sizeof(float));
    memset(bssqEn, 0, NSUB_MAX*sizeof(float));

    /* 最初の系列の前方を計算 */

    n=0;
    pp=residual;
    for (l=0; l<5; l++) {
        fssqEn[n] += sampEn_win[l] * (*pp) * (*pp);
        pp++;
    }
    for (l=5; l<SUBL; l++) {
        fssqEn[n] += (*pp) * (*pp);
        pp++;
    }

    /* 中間のすべての系列の前方と後方を計算 */

    for (n=1; n<iLBCenc_inst->nsub-1; n++) {
        pp=residual+n*SUBL;
        for (l=0; l<5; l++) {
            fssqEn[n] += sampEn_win[l] * (*pp) * (*pp);
            bssqEn[n] += (*pp) * (*pp);
            pp++;
        }
        for (l=5; l<SUBL-5; l++) {
            fssqEn[n] += (*pp) * (*pp);
            bssqEn[n] += (*pp) * (*pp);
            pp++;
        }
        for (l=SUBL-5; l<SUBL; l++) {
            fssqEn[n] += (*pp) * (*pp);
            bssqEn[n] += sampEn_win[SUBL-l-1] * (*pp) * (*pp);
            pp++;
        }
    }

    /* 最後の系列の後方を計算 */

    n=iLBCenc_inst->nsub-1;
    pp=residual+n*SUBL;
    for (l=0; l<SUBL-5; l++) {
        bssqEn[n] += (*pp) * (*pp);
        pp++;
    }
    for (l=SUBL-5; l<SUBL; l++) {
        bssqEn[n] += sampEn_win[SUBL-l-1] * (*pp) * (*pp);
        pp++;
    }

    /* 重み付けした80サンプルのうち、エネルギーが最大の
       もののインデックスを求める */

    if (iLBCenc_inst->mode==20) l=1;
    else                        l=0;

    max_ssqEn=(fssqEn[0]+bssqEn[1])*ssqEn_win[l];
    max_ssqEn_n=1;
    for (n=2; n<iLBCenc_inst->nsub; n++) {
        l++;
        if ((fssqEn[n-1]+bssqEn[n])*ssqEn_win[l] > max_ssqEn) {
            max_ssqEn=(fssqEn[n-1]+bssqEn[n]) *
                            ssqEn_win[l];
            max_ssqEn_n=n;
        }
    }

    return max_ssqEn_n;
}

