#ifndef __iLBC_GAINQUANT_H #define __iLBC_GAINQUANT_H
float gainquant(/* (o) 量子化したゲイン値 */ float in, /* (i) ゲイン値 */ float maxIn,/* (i) ゲイン値の最大値 */ int cblen, /* (i) 量子化インデックスの数 */ int *index /* (o) 量子化インデックス */ );
float gaindequant( /* (o) 量子化したゲイン値 */ int index, /* (i) 量子化インデックス */ float maxIn,/* (i) 量子化前のゲインの最大値 */ int cblen /* (i) 量子化インデックスの数 */ );
#endif

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code
    gainquant.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include <string.h>
#include <math.h>
#include "constants.h"
#include "filter.h"

/*----------------------------------------------------------------*
 *  残差のゲイン・シェイプ符号化におけるゲインの量子化器
 *---------------------------------------------------------------*/

float gainquant(/* (o) 量子化したゲイン値 */
    float in,       /* (i) ゲイン値 */
    float maxIn,/* (i) ゲイン値の最大値 */
    int cblen,      /* (i) 量子化インデックスの数 */
    int *index      /* (o) 量子化インデックス */
){
    int i, tindex;
    float minmeasure,measure, *cb, scale;

    /* スケーリング係数の下限を保証する */

    scale=maxIn;

    if (scale<0.1) {
        scale=(float)0.1;
    }

    /* 量子化テーブルを選択 */

    if (cblen == 8) {
        cb = gain_sq3Tbl;
    } else if (cblen == 16) {
        cb = gain_sq4Tbl;
    } else  {
        cb = gain_sq5Tbl;
    }

    /* 量子化テーブル内で最良のインデックスを選択 */

    minmeasure=10000000.0;
    tindex=0;
    for (i=0; i<cblen; i++) {
        measure=(in-scale*cb[i])*(in-scale*cb[i]);

        if (measure<minmeasure) {
            tindex=i;
            minmeasure=measure;
        }
    }
    *index=tindex;

    /* 量子化した値を返す */

    return scale*cb[tindex];
}

/*----------------------------------------------------------------*
 *  残差のゲイン・シェイプ符号化における量子化したゲインの
 *  デコーダー
 *---------------------------------------------------------------*/

float gaindequant(  /* (o) 量子化したゲイン値 */
    int index,      /* (i) 量子化インデックス */
    float maxIn,/* (i) 量子化前のゲインの最大値 */
    int cblen       /* (i) 量子化インデックスの数 */
){
    float scale;

    /* 正しいスケール係数を得る */

    scale=(float)fabs(maxIn);

    if (scale<0.1) {
        scale=(float)0.1;
    }

    /* 量子化テーブルを選択し、復号した値を返す */

    if (cblen==8) {
        return scale*gain_sq3Tbl[index];
    } else if (cblen==16) {
        return scale*gain_sq4Tbl[index];
    }
    else if (cblen==32) {
        return scale*gain_sq5Tbl[index];
    }

    return 0.0;
}

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    getCBvec.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include "iLBC_define.h"
#include "constants.h"
#include <string.h>

/*----------------------------------------------------------------*
 *  与えられたインデックスに対するコードブックベクトルを構成する。
 *---------------------------------------------------------------*/

void getCBvec(
    float *cbvec,   /* (o) 構成したコードブックベクトル */
    float *mem,     /* (i) コードブックバッファー */
    int index,      /* (i) コードブックインデックス */
    int lMem,       /* (i) コードブックバッファーの長さ */
    int cbveclen/* (i) コードブックベクトルの長さ */
){
    int j, k, n, memInd, sFilt;
    float tmpbuf[CB_MEML];
    int base_size;
    int ilow, ihigh;
    float alfa, alfa1;

    /* コードブックの各セクションのサイズを決定 */

    base_size=lMem-cbveclen+1;

    if (cbveclen==SUBL) {
        base_size+=cbveclen/2;
    }

    /* フィルターなし -> 最初のコードブックセクション */

    if (index<lMem-cbveclen+1) {

        /* 最初の補間しないベクトル */

        k=index+cbveclen;
        /* ベクトルを取得 */
        memcpy(cbvec, mem+lMem-k, cbveclen*sizeof(float));

    } else if (index < base_size) {

        k=2*(index-(lMem-cbveclen+1))+cbveclen;

        ihigh=k/2;
        ilow=ihigh-5;

        /* 補間しない最初の部分をコピー */

        memcpy(cbvec, mem+lMem-k/2, ilow*sizeof(float));

        /* 補間 */

        alfa1=(float)0.2;
        alfa=0.0;
        for (j=ilow; j<ihigh; j++) {
            cbvec[j]=((float)1.0-alfa)*mem[lMem-k/2+j]+
                alfa*mem[lMem-k+j];
            alfa+=alfa1;
        }

        /* 補間しない2番目の部分をコピー */

        memcpy(cbvec+ihigh, mem+lMem-k+ihigh,
            (cbveclen-ihigh)*sizeof(float));

    }

    /* フィルタリングに基づく上位のコードブックセクション */

    else {

        /* 最初の補間しないベクトル */

        if (index-base_size<lMem-cbveclen+1) {
            float tempbuff2[CB_MEML+CB_FILTERLEN+1];
            float *pos;
            float *pp, *pp1;

            memset(tempbuff2, 0,
                CB_HALFFILTERLEN*sizeof(float));
            memcpy(&tempbuff2[CB_HALFFILTERLEN], mem,
                lMem*sizeof(float));
            memset(&tempbuff2[lMem+CB_HALFFILTERLEN], 0,
                (CB_HALFFILTERLEN+1)*sizeof(float));

            k=index-base_size+cbveclen;
            sFilt=lMem-k;
            memInd=sFilt+1-CB_HALFFILTERLEN;

            /* フィルタリングを行う */
            pos=cbvec;
            memset(pos, 0, cbveclen*sizeof(float));
            for (n=0; n<cbveclen; n++) {
                pp=&tempbuff2[memInd+n+CB_HALFFILTERLEN];
                pp1=&cbfiltersTbl[CB_FILTERLEN-1];
                for (j=0; j<CB_FILTERLEN; j++) {
                    (*pos)+=(*pp++)*(*pp1--);
                }
                pos++;
            }
        }

        /* 補間したベクトル */

        else {
            float tempbuff2[CB_MEML+CB_FILTERLEN+1];

            float *pos;
            float *pp, *pp1;
            int i;

            memset(tempbuff2, 0,
                CB_HALFFILTERLEN*sizeof(float));
            memcpy(&tempbuff2[CB_HALFFILTERLEN], mem,
                lMem*sizeof(float));
            memset(&tempbuff2[lMem+CB_HALFFILTERLEN], 0,
                (CB_HALFFILTERLEN+1)*sizeof(float));

            k=2*(index-base_size-
                (lMem-cbveclen+1))+cbveclen;
            sFilt=lMem-k;
            memInd=sFilt+1-CB_HALFFILTERLEN;

            /* フィルタリングを行う */
            pos=&tmpbuf[sFilt];
            memset(pos, 0, k*sizeof(float));
            for (i=0; i<k; i++) {
                pp=&tempbuff2[memInd+i+CB_HALFFILTERLEN];
                pp1=&cbfiltersTbl[CB_FILTERLEN-1];
                for (j=0; j<CB_FILTERLEN; j++) {
                    (*pos)+=(*pp++)*(*pp1--);
                }
                pos++;
            }

            ihigh=k/2;
            ilow=ihigh-5;

            /* 補間しない最初の部分をコピー */

            memcpy(cbvec, tmpbuf+lMem-k/2,
                ilow*sizeof(float));

            /* 補間 */

            alfa1=(float)0.2;
            alfa=0.0;
            for (j=ilow; j<ihigh; j++) {
                cbvec[j]=((float)1.0-alfa)*
                    tmpbuf[lMem-k/2+j]+alfa*tmpbuf[lMem-k+j];
                alfa+=alfa1;
            }
            /* 補間しない2番目の部分をコピー */

            memcpy(cbvec+ihigh, tmpbuf+lMem-k+ihigh,
                (cbveclen-ihigh)*sizeof(float));
        }
    }
}

