#include <math.h>

#include "iLBC_define.h"
#include "constants.h"

/*----------------------------------------------------------------*
 *  自己相関の計算
 *---------------------------------------------------------------*/

void autocorr(
    float *r,       /* (o) 自己相関ベクトル */
    const float *x, /* (i) データベクトル */
    int N,          /* (i) データベクトルの長さ */
    int order       /* 計算する自己相関の
                       最大ラグ */
){
    int     lag, n;
    float   sum;

    for (lag = 0; lag <= order; lag++) {
        sum = 0;
        for (n = 0; n < N - lag; n++) {
            sum += x[n] * x[n+lag];
        }
        r[lag] = sum;
    }
}

/*----------------------------------------------------------------*
 *  窓の乗算
 *---------------------------------------------------------------*/

void window(
    float *z,       /* (o) 窓をかけたデータ */
    const float *x, /* (i) 元のデータベクトル */
    const float *y, /* (i) 窓 */
    int N           /* (i) すべてのベクトルの長さ */
){
    int     i;

    for (i = 0; i < N; i++) {
        z[i] = x[i] * y[i];
    }
}

/*----------------------------------------------------------------*
 *  レビンソン・ダービン法によるLPC係数の求解
 *---------------------------------------------------------------*/

void levdurb(
    float *a,       /* (o) 1.0で始まるLPC係数
                           ベクトル */
    float *k,       /* (o) 反射係数 */
    float *r,       /* (i) 自己相関ベクトル */
    int order       /* (i) LPCフィルターの次数 */
){
    float  sum, alpha;
    int     m, m_h, i;

    a[0] = 1.0;

    if (r[0] < EPS) { /* r[0] <= 0ならLPC係数をゼロにする */
        for (i = 0; i < order; i++) {
            k[i] = 0;
            a[i+1] = 0;
        }
    } else {
        a[1] = k[0] = -r[1]/r[0];
        alpha = r[0] + r[1] * k[0];
        for (m = 1; m < order; m++){
            sum = r[m + 1];
            for (i = 0; i < m; i++){
                sum += a[i+1] * r[m - i];
            }
            k[m] = -sum / alpha;
            alpha += k[m] * sum;
            m_h = (m + 1) >> 1;
            for (i = 0; i < m_h; i++){
                sum = a[i+1] + k[m] * a[m - i];
                a[m - i] += k[m] * a[i+1];
                a[i+1] = sum;
            }
            a[m+1] = k[m];
        }
    }
}

/*----------------------------------------------------------------*
 *  ベクトル間の補間
 *---------------------------------------------------------------*/

void interpolate(
    float *out,      /* (o) 補間したベクトル */
    float *in1,     /* (i) 補間に使う1番目の
                           ベクトル */
    float *in2,     /* (i) 補間に使う2番目の
                           ベクトル */
    float coef,      /* (i) 補間の重み */
    int length      /* (i) すべてのベクトルの長さ */
){
    int i;
    float invcoef;

    invcoef = (float)1.0 - coef;
    for (i = 0; i < length; i++) {
        out[i] = coef * in1[i] + invcoef * in2[i];
    }
}

/*----------------------------------------------------------------*
 *  LPCの帯域幅拡張
 *---------------------------------------------------------------*/

void bwexpand(
    float *out,      /* (o) 帯域幅拡張したLPC
                           係数 */
    float *in,      /* (i) 帯域幅拡張前の
                           LPC係数 */
    float coef,     /* (i) 帯域幅拡張係数 */
    int length      /* (i) LPC係数ベクトルの長さ */
){
    int i;
    float  chirp;

    chirp = coef;

    out[0] = in[0];
    for (i = 1; i < length; i++) {
        out[i] = chirp * in[i];
        chirp *= coef;
    }
}

/*----------------------------------------------------------------*
 *  ベクトル量子化
 *---------------------------------------------------------------*/

void vq(
    float *Xq,      /* (o) 量子化したベクトル */
    int *index,     /* (o) 量子化インデックス */
    const float *CB,/* (i) ベクトル量子化のコードブック */
    float *X,       /* (i) 量子化するベクトル */
    int n_cb,       /* (i) コードブック内のベクトルの数 */
    int dim         /* (i) すべてのベクトルの次元 */
){
    int     i, j;
    int     pos, minindex;
    float   dist, tmp, mindist;

    pos = 0;
    mindist = FLOAT_MAX;
    minindex = 0;
    for (j = 0; j < n_cb; j++) {
        dist = X[0] - CB[pos];
        dist *= dist;
        for (i = 1; i < dim; i++) {
            tmp = X[i] - CB[pos + i];
            dist += tmp*tmp;
        }

        if (dist < mindist) {
            mindist = dist;
            minindex = j;
        }
        pos += dim;
    }
    for (i = 0; i < dim; i++) {
        Xq[i] = CB[minindex*dim + i];
    }
    *index = minindex;
}

/*----------------------------------------------------------------*
 *  分割ベクトル量子化
 *---------------------------------------------------------------*/

void SplitVQ(
    float *qX,      /* (o) 量子化したベクトル */
    int *index,     /* (o) 分割したすべてのベクトルコードブック
                           に対するインデックスのベクトル */
    float *X,       /* (i) 量子化するベクトル */
    const float *CB,/* (i) 量子化器のコードブック */
    int nsplit,     /* ベクトルの分割数 */
    const int *dim, /* XとqXの次元 */
    const int *cbsize /* コードブック内のベクトルの数 */
){
    int    cb_pos, X_pos, i;

    cb_pos = 0;
    X_pos= 0;
    for (i = 0; i < nsplit; i++) {
        vq(qX + X_pos, index + i, CB + cb_pos, X + X_pos,
            cbsize[i], dim[i]);
        X_pos += dim[i];
        cb_pos += dim[i] * cbsize[i];
    }
}

/*----------------------------------------------------------------*
 *  スカラー量子化
 *---------------------------------------------------------------*/

void sort_sq(
    float *xq,      /* (o) 量子化した値 */
    int *index,     /* (o) 量子化インデックス */
    float x,    /* (i) 量子化する値 */
    const float *cb,/* (i) 量子化のコードブック */
    int cb_size      /* (i) 量子化のコードブックのサイズ */
){
    int i;

    if (x <= cb[0]) {
        *index = 0;
        *xq = cb[0];
    } else {
        i = 0;
        while ((x > cb[i]) && i < cb_size - 1) {
            i++;
        }

        if (x > ((cb[i] + cb[i - 1])/2)) {
            *index = i;
            *xq = cb[i];
        } else {
            *index = i - 1;
            *xq = cb[i - 1];
        }
    }
}

/*----------------------------------------------------------------*
 *  LSF係数の安定性の検査
 *---------------------------------------------------------------*/

int LSF_check(    /* (o) LSFベクトルが安定なら1、不安定
                           なら0 */
    float *lsf,     /* (i) LSFベクトルのテーブル */
    int dim,    /* (i) 各LSFベクトルの次元 */
    int NoAn    /* (i) テーブル内のLSFベクトルの
                           数 */
){
    int k,n,m, Nit=2, change=0,pos;
    float tmp;
    static float eps=(float)0.039; /* 50Hz */
    static float eps2=(float)0.0195;
    static float maxlsf=(float)3.14; /* 4000Hz */
    static float minlsf=(float)0.01; /* 0Hz */

    /* LSFの間隔の検査 */

    for (n=0; n<Nit; n++) { /* 何回か繰り返す */
        for (m=0; m<NoAn; m++) { /* フレームあたりの分析回数 */
            for (k=0; k<(dim-1); k++) {
                pos=m*dim+k;

                if ((lsf[pos+1]-lsf[pos])<eps) {

                    if (lsf[pos+1]<lsf[pos]) {
                        tmp=lsf[pos+1];
                        lsf[pos+1]= lsf[pos]+eps2;
                        lsf[pos]= lsf[pos+1]-eps2;
                    } else {
                        lsf[pos]-=eps2;
                        lsf[pos+1]+=eps2;
                    }
                    change=1;
                }

                if (lsf[pos]<minlsf) {
                    lsf[pos]=minlsf;
                    change=1;
                }

                if (lsf[pos]>maxlsf) {
                    lsf[pos]=maxlsf;
                    change=1;
                }
            }
        }
    }

    return change;
}

