#include "constants.h"

/*----------------------------------------------------------------*
 *  入力のハイパスフィルター
 *---------------------------------------------------------------*/

void hpInput(
    float *In,  /* (i) フィルターをかけるベクトル */
    int len,    /* (i) フィルターをかけるベクトルの長さ */
    float *Out, /* (o) フィルターをかけた結果のベクトル */
    float *mem  /* (i/o) フィルター状態 */
){
    int i;
    float *pi, *po;

    /* 全零部分 */

    pi = &In[0];
    po = &Out[0];
    for (i=0; i<len; i++) {
        *po = hpi_zero_coefsTbl[0] * (*pi);
        *po += hpi_zero_coefsTbl[1] * mem[0];
        *po += hpi_zero_coefsTbl[2] * mem[1];

        mem[1] = mem[0];
        mem[0] = *pi;
        po++;
        pi++;

    }

    /* 全極部分 */

    po = &Out[0];
    for (i=0; i<len; i++) {
        *po -= hpi_pole_coefsTbl[1] * mem[2];
        *po -= hpi_pole_coefsTbl[2] * mem[3];

        mem[3] = mem[2];
        mem[2] = *po;
        po++;
    }
}

