#ifndef __iLBC_ICBCONSTRUCT_H #define __iLBC_ICBCONSTRUCT_H
void index_conv_enc( int *index /* (i/o) コードブックインデックス */ );
void index_conv_dec( int *index /* (i/o) コードブックインデックス */ );
void iCBConstruct( float *decvector, /* (o) 復号したベクトル */ int *index, /* (i) コードブックインデックス */ int *gain_index,/* (i) ゲイン量子化インデックス */ float *mem, /* (i) コードベクトル構築用バッファー */ int lMem, /* (i) バッファーの長さ */ int veclen, /* (i) ベクトルの長さ */ int nStages /* (i) コードブックのステージ数 */ );
#endif

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    iCBConstruct.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include <math.h>

#include "iLBC_define.h"
#include "gainquant.h"
#include "getCBvec.h"

/*----------------------------------------------------------------*
 *  探索しやすいようにコードブックインデックスを変換
 *---------------------------------------------------------------*/
void index_conv_enc(
    int *index          /* (i/o) コードブックインデックス */
){
    int k;

    for (k=1; k<CB_NSTAGES; k++) {

        if ((index[k]>=108)&&(index[k]<172)) {
            index[k]-=64;
        } else if (index[k]>=236) {
            index[k]-=128;
        } else {
            /* エラー */
        }
    }
}

void index_conv_dec(
    int *index          /* (i/o) コードブックインデックス */
){
    int k;

    for (k=1; k<CB_NSTAGES; k++) {

        if ((index[k]>=44)&&(index[k]<108)) {
            index[k]+=64;
        } else if ((index[k]>=108)&&(index[k]<128)) {
            index[k]+=128;
        } else {
            /* エラー */
        }
    }
}

/*----------------------------------------------------------------*
 *  コードブックとゲインから復号ベクトルを構築する。
 *---------------------------------------------------------------*/

void iCBConstruct(
    float *decvector,   /* (o) 復号したベクトル */
    int *index,         /* (i) コードブックインデックス */
    int *gain_index,/* (i) ゲイン量子化インデックス */
    float *mem,         /* (i) コードベクトル構築用バッファー */
    int lMem,           /* (i) バッファーの長さ */
    int veclen,         /* (i) ベクトルの長さ */
    int nStages         /* (i) コードブックのステージ数 */
){
    int j,k;
    float gain[CB_NSTAGES];
    float cbvec[SUBL];

    /* ゲインの逆量子化 */

    gain[0] = gaindequant(gain_index[0], 1.0, 32);
    if (nStages > 1) {
        gain[1] = gaindequant(gain_index[1],
            (float)fabs(gain[0]), 16);
    }
    if (nStages > 2) {
        gain[2] = gaindequant(gain_index[2],
            (float)fabs(gain[1]), 8);
    }

    /* コードブックベクトルの構築と
    全体ベクトルの構築 */

    getCBvec(cbvec, mem, index[0], lMem, veclen);
    for (j=0;j<veclen;j++){
        decvector[j] = gain[0]*cbvec[j];
    }
    if (nStages > 1) {
        for (k=1; k<nStages; k++) {
            getCBvec(cbvec, mem, index[k], lMem, veclen);
            for (j=0;j<veclen;j++) {
                decvector[j] += gain[k]*cbvec[j];
            }
        }
    }
}

