#ifndef __iLBC_LPC_DECODE_H #define __iLBC_LPC_DECODE_H
void LSFinterpolate2a_dec( float *a, /* (o) サブフレームのLPC係数 */ float *lsf1, /* (i) 1つ目のLSF係数ベクトル */ float *lsf2, /* (i) 2つ目のLSF係数ベクトル */ float coef, /* (i) 補間の重み */ int length /* (i) LSFベクトルの長さ */ );
void SimplelsfDEQ( float *lsfdeq, /* (o) 逆量子化したLSF係数 */ int *index, /* (i) 量子化インデックス */ int lpc_n /* (i) LPCの数 */ );
void DecoderInterpolateLSF( float *syntdenum, /* (o) 合成フィルターの係数 */ float *weightdenum, /* (o) 重み付けフィルターの分母の 係数 */ float *lsfdeq, /* (i) 逆量子化したLSF係数 */ int length, /* (i) LSF係数ベクトルの長さ */ iLBC_Dec_Inst_t *iLBCdec_inst /* (i) デコーダー状態の構造体 */ );
#endif

