#include <math.h>
#include <string.h>

#include "helpfun.h"
#include "lsf.h"
#include "iLBC_define.h"
#include "constants.h"

/*---------------------------------------------------------------*
 *  デコーダー用のLSF係数の補間
 *--------------------------------------------------------------*/

void LSFinterpolate2a_dec(
    float *a,           /* (o) サブフレームのLPC係数 */
    float *lsf1,    /* (i) 1つ目のLSF係数ベクトル */
    float *lsf2,    /* (i) 2つ目のLSF係数ベクトル */
    float coef,         /* (i) 補間の重み */
    int length          /* (i) LSFベクトルの長さ */
){
    float  lsftmp[LPC_FILTERORDER];

    interpolate(lsftmp, lsf1, lsf2, coef, length);
    lsf2a(a, lsftmp);
}

/*---------------------------------------------------------------*
 *  量子化インデックスから逆量子化したLSF係数を得る
 *--------------------------------------------------------------*/

void SimplelsfDEQ(
    float *lsfdeq,    /* (o) 逆量子化したLSF係数 */
    int *index,         /* (i) 量子化インデックス */
    int lpc_n           /* (i) LPCの数 */
){
    int i, j, pos, cb_pos;
    /* 最初のLSFを復号 */

    pos = 0;
    cb_pos = 0;
    for (i = 0; i < LSF_NSPLIT; i++) {
        for (j = 0; j < dim_lsfCbTbl[i]; j++) {
            lsfdeq[pos + j] = lsfCbTbl[cb_pos +
                (long)(index[i])*dim_lsfCbTbl[i] + j];
        }
        pos += dim_lsfCbTbl[i];
        cb_pos += size_lsfCbTbl[i]*dim_lsfCbTbl[i];
    }

    if (lpc_n>1) {

        /* 最後のLSFを復号 */

        pos = 0;
        cb_pos = 0;
        for (i = 0; i < LSF_NSPLIT; i++) {
            for (j = 0; j < dim_lsfCbTbl[i]; j++) {
                lsfdeq[LPC_FILTERORDER + pos + j] =
                    lsfCbTbl[cb_pos +
                    (long)(index[LSF_NSPLIT + i])*
                    dim_lsfCbTbl[i] + j];
            }
            pos += dim_lsfCbTbl[i];
            cb_pos += size_lsfCbTbl[i]*dim_lsfCbTbl[i];
        }
    }
}

/*----------------------------------------------------------------*
 *  LSF係数から合成フィルターと重み付けフィルターを得る
 *---------------------------------------------------------------*/

void DecoderInterpolateLSF(
    float *syntdenum, /* (o) 合成フィルターの係数 */
    float *weightdenum, /* (o) 重み付けフィルターの分母の
                               係数 */
    float *lsfdeq,       /* (i) 逆量子化したLSF係数 */
    int length,         /* (i) LSF係数ベクトルの長さ */
    iLBC_Dec_Inst_t *iLBCdec_inst
                        /* (i) デコーダー状態の構造体 */
){
    int    i, pos, lp_length;
    float  lp[LPC_FILTERORDER + 1], *lsfdeq2;
    lsfdeq2 = lsfdeq + length;
    lp_length = length + 1;

    if (iLBCdec_inst->mode==30) {
        /* サブフレーム1: 前回のものと1つ目の間で補間 */

        LSFinterpolate2a_dec(lp, iLBCdec_inst->lsfdeqold, lsfdeq,
            lsf_weightTbl_30ms[0], length);
        memcpy(syntdenum,lp,lp_length*sizeof(float));
        bwexpand(weightdenum, lp, LPC_CHIRP_WEIGHTDENUM,
            lp_length);

        /* サブフレーム2から6: 最初のLSFと最後のLSFの
           間で補間 */

        pos = lp_length;
        for (i = 1; i < 6; i++) {
            LSFinterpolate2a_dec(lp, lsfdeq, lsfdeq2,
                lsf_weightTbl_30ms[i], length);
            memcpy(syntdenum + pos,lp,lp_length*sizeof(float));
            bwexpand(weightdenum + pos, lp,
                LPC_CHIRP_WEIGHTDENUM, lp_length);
            pos += lp_length;
        }
    }
    else {
        pos = 0;
        for (i = 0; i < iLBCdec_inst->nsub; i++) {
            LSFinterpolate2a_dec(lp, iLBCdec_inst->lsfdeqold,
                lsfdeq, lsf_weightTbl_20ms[i], length);
            memcpy(syntdenum+pos,lp,lp_length*sizeof(float));
            bwexpand(weightdenum+pos, lp, LPC_CHIRP_WEIGHTDENUM,
                lp_length);
            pos += lp_length;
        }
    }

    /* メモリーを更新 */

    if (iLBCdec_inst->mode==30)
        memcpy(iLBCdec_inst->lsfdeqold, lsfdeq2,
                    length*sizeof(float));
    else
        memcpy(iLBCdec_inst->lsfdeqold, lsfdeq,
                    length*sizeof(float));

}

