#include <string.h>

#include "iLBC_define.h"
#include "helpfun.h"
#include "lsf.h"
#include "constants.h"
/*----------------------------------------------------------------*
 *  LPC分析（LPCencodeのサブルーチン）
 *---------------------------------------------------------------*/

void SimpleAnalysis(
    float *lsf,         /* (o) LSF係数 */
    float *data,    /* (i) 新しいデータベクトル */
    iLBC_Enc_Inst_t *iLBCenc_inst
                        /* (i/o) エンコーダー状態の構造体 */
){
    int k, is;
    float temp[BLOCKL_MAX], lp[LPC_FILTERORDER + 1];
    float lp2[LPC_FILTERORDER + 1];
    float r[LPC_FILTERORDER + 1];

    is=LPC_LOOKBACK+BLOCKL_MAX-iLBCenc_inst->blockl;
    memcpy(iLBCenc_inst->lpc_buffer+is,data,
        iLBCenc_inst->blockl*sizeof(float));

    /* 先読みなし、最後の窓は非対称 */

    for (k = 0; k < iLBCenc_inst->lpc_n; k++) {

        is = LPC_LOOKBACK;

        if (k < (iLBCenc_inst->lpc_n - 1)) {
            window(temp, lpc_winTbl,
                iLBCenc_inst->lpc_buffer, BLOCKL_MAX);
        } else {
            window(temp, lpc_asymwinTbl,
                iLBCenc_inst->lpc_buffer + is, BLOCKL_MAX);
        }

        autocorr(r, temp, BLOCKL_MAX, LPC_FILTERORDER);
        window(r, r, lpc_lagwinTbl, LPC_FILTERORDER + 1);

        levdurb(lp, temp, r, LPC_FILTERORDER);
        bwexpand(lp2, lp, LPC_CHIRP_SYNTDENUM, LPC_FILTERORDER+1);

        a2lsf(lsf + k*LPC_FILTERORDER, lp2);
    }
    is=LPC_LOOKBACK+BLOCKL_MAX-iLBCenc_inst->blockl;
    memmove(iLBCenc_inst->lpc_buffer,
        iLBCenc_inst->lpc_buffer+LPC_LOOKBACK+BLOCKL_MAX-is,
        is*sizeof(float));
}

/*----------------------------------------------------------------*
 *  LSFの補間と、LSFからa係数への変換
 *  （SimpleInterpolateLSFのサブルーチン）
 *---------------------------------------------------------------*/

void LSFinterpolate2a_enc(
    float *a,       /* (o) LPC係数 */
    float *lsf1,/* (i) 1組目のLSF係数 */
    float *lsf2,/* (i) 2組目のLSF係数 */
    float coef,     /* (i) lsf1とlsf2の間で使う重み付け
                           係数 */
    long length      /* (i) 係数ベクトルの長さ */
){
    float  lsftmp[LPC_FILTERORDER];

    interpolate(lsftmp, lsf1, lsf2, coef, length);
    lsf2a(a, lsftmp);
}

/*----------------------------------------------------------------*
 *  LSFの補間（LPCencodeのサブルーチン）
 *---------------------------------------------------------------*/

void SimpleInterpolateLSF(
    float *syntdenum,   /* (o) 量子化して補間したLSFから
                               得られる合成フィルターの
                               分母 */
    float *weightdenum, /* (o) 量子化せずに補間したLSFから
                               得られる重み付けフィルターの
                               分母 */
    float *lsf,         /* (i) 量子化していないLSF係数 */
    float *lsfdeq,      /* (i) 逆量子化したLSF係数 */
    float *lsfold,      /* (i) 前の信号フレームの量子化して
                               いないLSF係数 */
    float *lsfdeqold, /* (i) 前の信号フレームの逆量子化した
                               LSF係数 */
    int length,         /* (i) LPC_FILTERORDERと等しいこと */
    iLBC_Enc_Inst_t *iLBCenc_inst
                        /* (i/o) エンコーダー状態の構造体 */
){
    int    i, pos, lp_length;
    float  lp[LPC_FILTERORDER + 1], *lsf2, *lsfdeq2;

    lsf2 = lsf + length;
    lsfdeq2 = lsfdeq + length;
    lp_length = length + 1;

    if (iLBCenc_inst->mode==30) {
        /* サブフレーム1: 前回のLSF係数と1組目のLSF係数の
           間で補間 */

        LSFinterpolate2a_enc(lp, lsfdeqold, lsfdeq,
            lsf_weightTbl_30ms[0], length);
        memcpy(syntdenum,lp,lp_length*sizeof(float));
        LSFinterpolate2a_enc(lp, lsfold, lsf,
            lsf_weightTbl_30ms[0], length);
        bwexpand(weightdenum, lp, LPC_CHIRP_WEIGHTDENUM, lp_length);

        /* サブフレーム2から6: 1組目のLSF係数と2組目の
           LSF係数の間で補間 */

        pos = lp_length;
        for (i = 1; i < iLBCenc_inst->nsub; i++) {
            LSFinterpolate2a_enc(lp, lsfdeq, lsfdeq2,
                lsf_weightTbl_30ms[i], length);
            memcpy(syntdenum + pos,lp,lp_length*sizeof(float));

            LSFinterpolate2a_enc(lp, lsf, lsf2,
                lsf_weightTbl_30ms[i], length);
            bwexpand(weightdenum + pos, lp,
                LPC_CHIRP_WEIGHTDENUM, lp_length);
            pos += lp_length;
        }
    }
    else {
        pos = 0;
        for (i = 0; i < iLBCenc_inst->nsub; i++) {
            LSFinterpolate2a_enc(lp, lsfdeqold, lsfdeq,
                lsf_weightTbl_20ms[i], length);
            memcpy(syntdenum+pos,lp,lp_length*sizeof(float));
            LSFinterpolate2a_enc(lp, lsfold, lsf,
                lsf_weightTbl_20ms[i], length);
            bwexpand(weightdenum+pos, lp,
                LPC_CHIRP_WEIGHTDENUM, lp_length);
            pos += lp_length;
        }
    }

    /* メモリーを更新 */

    if (iLBCenc_inst->mode==30) {
        memcpy(lsfold, lsf2, length*sizeof(float));
        memcpy(lsfdeqold, lsfdeq2, length*sizeof(float));
    }
    else {
        memcpy(lsfold, lsf, length*sizeof(float));
        memcpy(lsfdeqold, lsfdeq, length*sizeof(float));
    }
}

/*----------------------------------------------------------------*
 *  LSF量子化器（LPCencodeのサブルーチン）
 *---------------------------------------------------------------*/

void SimplelsfQ(
    float *lsfdeq,    /* (o) 逆量子化したLSF係数
                           （次元はFILTERORDER） */
    int *index,     /* (o) 量子化インデックス */
    float *lsf,      /* (i) 量子化するLSF係数ベクトル
                           （次元はFILTERORDER） */
    int lpc_n     /* (i) 量子化するLSFの組の数 */
){
    /* 1つ目のLSFをメモリーなしの分割VQで量子化 */
    SplitVQ(lsfdeq, index, lsf, lsfCbTbl, LSF_NSPLIT,
        dim_lsfCbTbl, size_lsfCbTbl);

    if (lpc_n==2) {
        /* 2つ目のLSFをメモリーなしの分割VQで量子化 */
        SplitVQ(lsfdeq + LPC_FILTERORDER, index + LSF_NSPLIT,
            lsf + LPC_FILTERORDER, lsfCbTbl, LSF_NSPLIT,
            dim_lsfCbTbl, size_lsfCbTbl);
    }
}

/*----------------------------------------------------------------*
 *  LPCエンコーダー
 *---------------------------------------------------------------*/

void LPCencode(
    float *syntdenum, /* (i/o) 符号化前/後の合成フィルター
                               係数 */
    float *weightdenum, /* (i/o) 符号化前/後の
                               重み付けフィルターの分母の
                               係数 */
    int *lsf_index,     /* (o) LSF量子化インデックス */
    float *data,    /* (i) 量子化するLSF係数 */
    iLBC_Enc_Inst_t *iLBCenc_inst
                        /* (i/o) エンコーダー状態の構造体 */
){
    float lsf[LPC_FILTERORDER * LPC_N_MAX];
    float lsfdeq[LPC_FILTERORDER * LPC_N_MAX];
    int change=0;

    SimpleAnalysis(lsf, data, iLBCenc_inst);
    SimplelsfQ(lsfdeq, lsf_index, lsf, iLBCenc_inst->lpc_n);
    change=LSF_check(lsfdeq, LPC_FILTERORDER, iLBCenc_inst->lpc_n);
    SimpleInterpolateLSF(syntdenum, weightdenum,
        lsf, lsfdeq, iLBCenc_inst->lsfold,
        iLBCenc_inst->lsfdeqold, LPC_FILTERORDER, iLBCenc_inst);
}

