#include <string.h>
#include <math.h>

#include "iLBC_define.h"

/*----------------------------------------------------------------*
 *  LPC係数からLSF係数への変換
 *---------------------------------------------------------------*/

void a2lsf(
    float *freq,/* (o) LSF係数 */
    float *a    /* (i) LPC係数 */
){
    float steps[LSF_NUMBER_OF_STEPS] =
        {(float)0.00635, (float)0.003175, (float)0.0015875,
        (float)0.00079375};
    float step;
    int step_idx;
    int lsp_index;
    float p[LPC_HALFORDER];
    float q[LPC_HALFORDER];
    float p_pre[LPC_HALFORDER];
    float q_pre[LPC_HALFORDER];
    float old_p, old_q, *old;
    float *pq_coef;
    float omega, old_omega;
    int i;
    float hlp, hlp1, hlp2, hlp3, hlp4, hlp5;

    for (i=0; i<LPC_HALFORDER; i++) {
        p[i] = (float)-1.0 * (a[i + 1] + a[LPC_FILTERORDER - i]);
        q[i] = a[LPC_FILTERORDER - i] - a[i + 1];
    }

    p_pre[0] = (float)-1.0 - p[0];
    p_pre[1] = - p_pre[0] - p[1];
    p_pre[2] = - p_pre[1] - p[2];
    p_pre[3] = - p_pre[2] - p[3];
    p_pre[4] = - p_pre[3] - p[4];
    p_pre[4] = p_pre[4] / 2;

    q_pre[0] = (float)1.0 - q[0];
    q_pre[1] = q_pre[0] - q[1];
    q_pre[2] = q_pre[1] - q[2];
    q_pre[3] = q_pre[2] - q[3];
    q_pre[4] = q_pre[3] - q[4];
    q_pre[4] = q_pre[4] / 2;

    omega = 0.0;
    old_omega = 0.0;

    old_p = FLOAT_MAX;
    old_q = FLOAT_MAX;

    /* ここでlsp_indexについてループし、omegaの
       LPC_FILTERORDER個の根をすべて求めます。 */

    for (lsp_index = 0; lsp_index<LPC_FILTERORDER; lsp_index++) {

        /* lsp_indexが偶数か奇数かに応じて、2つのLSP方程式の
        根を交互に解きます。 */


        if ((lsp_index & 0x1) == 0) {
            pq_coef = p_pre;
            old = &old_p;
        } else {
            pq_coef = q_pre;
            old = &old_q;
        }

        /* 低解像度のグリッドから開始 */

        for (step_idx = 0, step = steps[step_idx];
            step_idx < LSF_NUMBER_OF_STEPS;){

            /*  cos(10piw) + pq(0)cos(8piw) + pq(1)cos(6piw) +
            pq(2)cos(4piw) + pq(3)cod(2piw) + pq(4) */

            hlp = (float)cos(omega * TWO_PI);
            hlp1 = (float)2.0 * hlp + pq_coef[0];
            hlp2 = (float)2.0 * hlp * hlp1 - (float)1.0 +
                pq_coef[1];
            hlp3 = (float)2.0 * hlp * hlp2 - hlp1 + pq_coef[2];
            hlp4 = (float)2.0 * hlp * hlp3 - hlp2 + pq_coef[3];
            hlp5 = hlp * hlp4 - hlp3 + pq_coef[4];


            if (((hlp5 * (*old)) <= 0.0) || (omega >= 0.5)){

                if (step_idx == (LSF_NUMBER_OF_STEPS - 1)){

                    if (fabs(hlp5) >= fabs(*old)) {
                        freq[lsp_index] = omega - step;
                    } else {
                        freq[lsp_index] = omega;
                    }
                    if ((*old) >= 0.0){
                        *old = (float)-1.0 * FLOAT_MAX;
                    } else {
                        *old = FLOAT_MAX;
                    }

                    omega = old_omega;
                    step_idx = 0;

                    step_idx = LSF_NUMBER_OF_STEPS;
                } else {

                    if (step_idx == 0) {
                        old_omega = omega;
                    }

                    step_idx++;
                    omega -= steps[step_idx];

                    /* グリッドを1ステップ戻る */

                    step = steps[step_idx];
                }
            } else {

            /* 符号が異なり、omegaとold_omegaの間に少なくとも
            1つの根があるとわかるまでomegaを増やします */
                *old = hlp5;
                omega += step;
            }
        }
    }

    for (i = 0; i<LPC_FILTERORDER; i++) {
        freq[i] = freq[i] * TWO_PI;
    }
}

/*----------------------------------------------------------------*
 *  LSF係数からLPC係数への変換
 *---------------------------------------------------------------*/

void lsf2a(
    float *a_coef,  /* (o) LPC係数 */
    float *freq     /* (i) LSF係数 */
){
    int i, j;
    float hlp;
    float p[LPC_HALFORDER], q[LPC_HALFORDER];
    float a[LPC_HALFORDER + 1], a1[LPC_HALFORDER],
        a2[LPC_HALFORDER];
    float b[LPC_HALFORDER + 1], b1[LPC_HALFORDER],
        b2[LPC_HALFORDER];

    for (i=0; i<LPC_FILTERORDER; i++) {
        freq[i] = freq[i] * PI2;
    }

    /* 入力が悪条件でないかを確認します。この部分はTIA標準には
    ありません。以下の2つのIFブロックがこれにあたります。
    "freq"が悪条件と判断された場合、まずfreq[0]と
    freq[LPC_HALFORDER-1]を修正し（LPCの用途では通常
    LPC_HALFORDER = 10）、次にほかの"freq"の値をわずかに
    調整します */


    if ((freq[0] <= 0.0) || (freq[LPC_FILTERORDER - 1] >= 0.5)){


        if (freq[0] <= 0.0) {
            freq[0] = (float)0.022;
        }


        if (freq[LPC_FILTERORDER - 1] >= 0.5) {
            freq[LPC_FILTERORDER - 1] = (float)0.499;
        }

        hlp = (freq[LPC_FILTERORDER - 1] - freq[0]) /
            (float) (LPC_FILTERORDER - 1);

        for (i=1; i<LPC_FILTERORDER; i++) {
            freq[i] = freq[i - 1] + hlp;
        }
    }

    memset(a1, 0, LPC_HALFORDER*sizeof(float));
    memset(a2, 0, LPC_HALFORDER*sizeof(float));
    memset(b1, 0, LPC_HALFORDER*sizeof(float));
    memset(b2, 0, LPC_HALFORDER*sizeof(float));
    memset(a, 0, (LPC_HALFORDER+1)*sizeof(float));
    memset(b, 0, (LPC_HALFORDER+1)*sizeof(float));
    /* p[i]とq[i]は、式4.2.2.2-1と4.2.2.2-2の
    cos(2*pi*omega_{2j})とcos(2*pi*omega_{2j-1}を計算します。
    このコードでは、p[i]は.Q_A(z)で使う係数を指定し、q[i]は
    .P_A(z)で使う係数を指定することに注意してください */

    for (i=0; i<LPC_HALFORDER; i++) {
        p[i] = (float)cos(TWO_PI * freq[2 * i]);
        q[i] = (float)cos(TWO_PI * freq[2 * i + 1]);
    }

    a[0] = 0.25;
    b[0] = 0.25;

    for (i= 0; i<LPC_HALFORDER; i++) {
        a[i + 1] = a[i] - 2 * p[i] * a1[i] + a2[i];
        b[i + 1] = b[i] - 2 * q[i] * b1[i] + b2[i];
        a2[i] = a1[i];
        a1[i] = a[i];
        b2[i] = b1[i];
        b1[i] = b[i];
    }

    for (j=0; j<LPC_FILTERORDER; j++) {

        if (j == 0) {
            a[0] = 0.25;
            b[0] = -0.25;
        } else {
            a[0] = b[0] = 0.0;
        }

        for (i=0; i<LPC_HALFORDER; i++) {
            a[i + 1] = a[i] - 2 * p[i] * a1[i] + a2[i];
            b[i + 1] = b[i] - 2 * q[i] * b1[i] + b2[i];
            a2[i] = a1[i];
            a1[i] = a[i];
            b2[i] = b1[i];
            b1[i] = b[i];
        }

        a_coef[j + 1] = 2 * (a[LPC_HALFORDER] + b[LPC_HALFORDER]);
    }

    a_coef[0] = 1.0;
}

