#ifndef __PACKING_H #define __PACKING_H
void packsplit( int *index, /* (i) 分割する値 */ int *firstpart, /* (o) 上位ビットで表される値 */ int *rest, /* (o) 下位ビットで表される値 */ int bitno_firstpart, /* (i) 上位部分のビット数 */ int bitno_total /* (i) 値の全範囲のビット数 */ );
void packcombine( int *index, /* (i/o) 入力はmsbの値、出力は 結合した値 */ int rest, /* (i) lsbの値 */ int bitno_rest /* (i) lsb部分のビット数 */ );
void dopack( unsigned char **bitstream, /* (i/o) 入口では、新しいデータを 詰めるビットストリーム内の 位置へのポインター。出口では、 今後のデータを詰める ビットストリーム内の位置への ポインター */ int index, /* (i) 詰める値 */ int bitno, /* (i) 値が収まるビット数 */ int *pos /* (i/o) 現在のバイト内の 書き込み位置 */ ); void unpack( unsigned char **bitstream, /* (i/o) 入口では、新しいデータを 取り出すビットストリーム内の 位置へのポインター。出口では、 今後のデータを取り出す ビットストリーム内の位置への ポインター */ int *index, /* (o) 結果の値 */ int bitno, /* (i) 値を表すのに使うビット数 */ int *pos /* (i/o) 現在のバイト内の 読み取り位置 */ );
#endif

/******************************************************************

    iLBC Speech Coder ANSI-C Source Code

    packing.c

    Copyright (C) The Internet Society (2004).
    All Rights Reserved.

******************************************************************/

#include <math.h>
#include <stdlib.h>

#include "iLBC_define.h"
#include "constants.h"
#include "helpfun.h"
#include "string.h"

/*----------------------------------------------------------------*
 *  整数を、先頭の上位ビットと残りの下位ビットに分割
 *---------------------------------------------------------------*/

void packsplit(
    int *index,                 /* (i) 分割する値 */
    int *firstpart,             /* (o) 上位ビットで表される値 */
    int *rest,                  /* (o) 下位ビットで表される値 */
    int bitno_firstpart,    /* (i) 上位部分のビット数 */
    int bitno_total             /* (i) 値の全範囲のビット数 */
){
    int bitno_rest = bitno_total-bitno_firstpart;

    *firstpart = *index>>(bitno_rest);
    *rest = *index-(*firstpart<<(bitno_rest));
}

/*----------------------------------------------------------------*
 *  msbに対応する値とlsbに対応する値の結合
 *---------------------------------------------------------------*/

void packcombine(
    int *index,                 /* (i/o) 入力はmsbの値、出力は
                                       結合した値 */
    int rest,                   /* (i) lsbの値 */
    int bitno_rest              /* (i) lsb部分のビット数 */
){
    *index = *index<<bitno_rest;
    *index += rest;
}

/*----------------------------------------------------------------*
 *  ビットストリーム（つまりバイトのベクトル）へのビットの詰め込み
 *---------------------------------------------------------------*/

void dopack(
    unsigned char **bitstream,  /* (i/o) 入口では、新しいデータを
                                       詰めるビットストリーム内の
                                       位置へのポインター。出口では、
                                       今後のデータを詰める
                                       ビットストリーム内の位置への
                                       ポインター */
    int index,                  /* (i) 詰める値 */
    int bitno,                  /* (i) 値が収まるビット数 */
    int *pos                /* (i/o) 現在のバイト内の
                                       書き込み位置 */
){
    int posLeft;

    /* 新しいバイトを始める前にビットをクリア */

    if ((*pos)==0) {
        **bitstream=0;
    }

    while (bitno>0) {

        /* このバイトの終わりに達したら次のバイトへ移る*/

        if (*pos==8) {
            *pos=0;
            (*bitstream)++;
            **bitstream=0;
        }

        posLeft=8-(*pos);

        /* インデックスをビットストリームに挿入 */

        if (bitno <= posLeft) {
            **bitstream |= (unsigned char)(index<<(posLeft-bitno));
            *pos+=bitno;
            bitno=0;
        } else {
            **bitstream |= (unsigned char)(index>>(bitno-posLeft));

            *pos=8;
            index-=((index>>(bitno-posLeft))<<(bitno-posLeft));

            bitno-=posLeft;
        }
    }
}

/*----------------------------------------------------------------*
 *  ビットストリーム（つまりバイトのベクトル）からのビットの取り出し
 *---------------------------------------------------------------*/

void unpack(
    unsigned char **bitstream,  /* (i/o) 入口では、新しいデータを
                                       取り出すビットストリーム内の
                                       位置へのポインター。出口では、
                                       今後のデータを取り出す
                                       ビットストリーム内の位置への
                                       ポインター */
    int *index,                 /* (o) 結果の値 */
    int bitno,                  /* (i) 値を表すのに使うビット数 */
    int *pos                /* (i/o) 現在のバイト内の
                                       読み取り位置 */
){
    int BitsLeft;

    *index=0;

    while (bitno>0) {

        /* バイトの終わりに達したらビットストリーム内で
           先に進む */

        if (*pos==8) {
            *pos=0;
            (*bitstream)++;
        }

        BitsLeft=8-(*pos);

        /* ビットを取り出してインデックスに加える */

        if (BitsLeft>=bitno) {
            *index+=((((**bitstream)<<(*pos)) & 0xFF)>>(8-bitno));

            *pos+=bitno;
            bitno=0;
        } else {

            if ((8-bitno)>0) {
                *index+=((((**bitstream)<<(*pos)) & 0xFF)>>
                    (8-bitno));
                *pos=8;
            } else {
                *index+=(((int)(((**bitstream)<<(*pos)) & 0xFF))<<
                    (bitno-8));
                *pos=8;
            }
            bitno-=BitsLeft;
        }
    }
}

