#include <math.h>
#include <string.h>

#include "iLBC_define.h"
#include "constants.h"
#include "filter.h"

/*----------------------------------------------------------------*
 *  開始状態の復号
 *---------------------------------------------------------------*/

void StateConstructW(
    int idxForMax,      /* (i) 最大振幅を量子化した
                               6ビットのインデックス */
    int *idxVec,    /* (i) 量子化インデックスのベクトル */
    float *syntDenum,   /* (i) 合成フィルターの分母 */
    float *out,         /* (o) 復号した状態ベクトル */
    int len             /* (i) 状態ベクトルの長さ */
){
    float maxVal, tmpbuf[LPC_FILTERORDER+2*STATE_LEN], *tmp,
        numerator[LPC_FILTERORDER+1];
    float foutbuf[LPC_FILTERORDER+2*STATE_LEN], *fout;
    int k,tmpi;

    /* 最大値の復号 */

    maxVal = state_frgqTbl[idxForMax];
    maxVal = (float)pow(10,maxVal)/(float)4.5;

    /* バッファーと係数の初期化 */

    memset(tmpbuf, 0, LPC_FILTERORDER*sizeof(float));
    memset(foutbuf, 0, LPC_FILTERORDER*sizeof(float));
    for (k=0; k<LPC_FILTERORDER; k++) {
        numerator[k]=syntDenum[LPC_FILTERORDER-k];
    }
    numerator[LPC_FILTERORDER]=syntDenum[0];
    tmp = &tmpbuf[LPC_FILTERORDER];
    fout = &foutbuf[LPC_FILTERORDER];

    /* サンプル値の復号 */

    for (k=0; k<len; k++) {
        tmpi = len-1-k;
        /* maxVal = 1/scal */
        tmp[k] = maxVal*state_sq3Tbl[idxVec[tmpi]];
    }

    /* オールパスフィルターとの巡回畳み込み */

    memset(tmp+len, 0, len*sizeof(float));
    ZeroPoleFilter(tmp, numerator, syntDenum, 2*len,
        LPC_FILTERORDER, fout);
    for (k=0;k<len;k++) {
        out[k] = fout[len-1-k]+fout[2*len-1-k];
    }
}

