/*----------------------------------------------------------------*
 *  スケーリングした開始状態の予測ノイズシェーピング符号化
 *  （StateSearchWのサブルーチン）
 *---------------------------------------------------------------*/

void AbsQuantW(
    iLBC_Enc_Inst_t *iLBCenc_inst,
                        /* (i) エンコーダーインスタンス */
    float *in,          /* (i) 符号化するベクトル */
    float *syntDenum,   /* (i) 合成フィルターの分母 */
    float *weightDenum, /* (i) 重み付けフィルターの分母 */
    int *out,           /* (o) 量子化器インデックスのベクトル */
    int len,        /* (i) 符号化するベクトルと量子化器
                               インデックスのベクトルの長さ */
    int state_first     /* (i) 80サンプルのベクトル内での
                               開始状態の位置 */
){
    float *syntOut;
    float syntOutBuf[LPC_FILTERORDER+STATE_SHORT_LEN_30MS];
    float toQ, xq;
    int n;
    int index;

    /* フィルタリング用バッファーの初期化 */

    memset(syntOutBuf, 0, LPC_FILTERORDER*sizeof(float));
    /* フィルタリング用ポインターの初期化 */

    syntOut = &syntOutBuf[LPC_FILTERORDER];

    /* 入力に合成フィルターと重み付けフィルターを適用 */

    if (state_first) {
        AllPoleFilter (in, weightDenum, SUBL, LPC_FILTERORDER);
    } else {
        AllPoleFilter (in, weightDenum,
            iLBCenc_inst->state_short_len-SUBL,
            LPC_FILTERORDER);
    }

    /* 符号化ループ */

    for (n=0; n<len; n++) {

        /* フィルター係数の時間更新 */

        if ((state_first)&&(n==SUBL)){
            syntDenum += (LPC_FILTERORDER+1);
            weightDenum += (LPC_FILTERORDER+1);

            /* 入力に合成フィルターと重み付けフィルターを適用 */
            AllPoleFilter (&in[n], weightDenum, len-n,
                LPC_FILTERORDER);

        } else if ((state_first==0)&&
            (n==(iLBCenc_inst->state_short_len-SUBL))) {
            syntDenum += (LPC_FILTERORDER+1);
            weightDenum += (LPC_FILTERORDER+1);

            /* 入力に合成フィルターと重み付けフィルターを適用 */
            AllPoleFilter (&in[n], weightDenum, len-n,
                LPC_FILTERORDER);

        }

        /* 合成・重み付けした入力の予測 */

        syntOut[n] = 0.0;
        AllPoleFilter (&syntOut[n], weightDenum, 1,
            LPC_FILTERORDER);

        /* 量子化 */

        toQ = in[n]-syntOut[n];
        sort_sq(&xq, &index, toQ, state_sq3Tbl, 8);
        out[n]=index;
        syntOut[n] = state_sq3Tbl[out[n]];

        /* 予測フィルターの更新 */

        AllPoleFilter(&syntOut[n], weightDenum, 1,
            LPC_FILTERORDER);
    }
}

/*----------------------------------------------------------------*
 *  開始状態の符号化
 *---------------------------------------------------------------*/

void StateSearchW(
    iLBC_Enc_Inst_t *iLBCenc_inst,
                        /* (i) エンコーダーインスタンス */
    float *residual,/* (i) ターゲット残差ベクトル */
    float *syntDenum,   /* (i) LPC合成フィルター */
    float *weightDenum, /* (i) 重み付けフィルターの分母 */
    int *idxForMax,     /* (o) 最大振幅の量子化器
                               インデックス */
    int *idxVec,    /* (o) 量子化インデックスのベクトル */
    int len,        /* (i) すべてのベクトルの長さ */
    int state_first     /* (i) 80サンプルのベクトル内での
                               開始状態の位置 */
){
    float dtmp, maxVal;
    float tmpbuf[LPC_FILTERORDER+2*STATE_SHORT_LEN_30MS];
    float *tmp, numerator[1+LPC_FILTERORDER];
    float foutbuf[LPC_FILTERORDER+2*STATE_SHORT_LEN_30MS], *fout;
    int k;
    float qmax, scal;

    /* バッファーとフィルター係数の初期化 */

    memset(tmpbuf, 0, LPC_FILTERORDER*sizeof(float));
    memset(foutbuf, 0, LPC_FILTERORDER*sizeof(float));
    for (k=0; k<LPC_FILTERORDER; k++) {
        numerator[k]=syntDenum[LPC_FILTERORDER-k];
    }
    numerator[LPC_FILTERORDER]=syntDenum[0];
    tmp = &tmpbuf[LPC_FILTERORDER];
    fout = &foutbuf[LPC_FILTERORDER];

    /* オールパスフィルターとの巡回畳み込み */
    memcpy(tmp, residual, len*sizeof(float));
    memset(tmp+len, 0, len*sizeof(float));
    ZeroPoleFilter(tmp, numerator, syntDenum, 2*len,
        LPC_FILTERORDER, fout);
    for (k=0; k<len; k++) {
        fout[k] += fout[k+len];
    }

    /* 最大振幅値の特定 */

    maxVal = fout[0];
    for (k=1; k<len; k++) {

        if (fout[k]*fout[k] > maxVal*maxVal){
            maxVal = fout[k];
        }
    }
    maxVal=(float)fabs(maxVal);

    /* 最大振幅値の符号化 */

    if (maxVal < 10.0) {
        maxVal = 10.0;
    }
    maxVal = (float)log10(maxVal);
    sort_sq(&dtmp, idxForMax, maxVal, state_frgqTbl, 64);

    /* 最大振幅の代表値を復号し、それに応じて開始状態を
       スケーリング */

    maxVal=state_frgqTbl[*idxForMax];
    qmax = (float)pow(10,maxVal);
    scal = (float)(4.5)/qmax;
    for (k=0; k<len; k++){
        fout[k] *= scal;
    }

    /* スケーリングした開始状態の予測ノイズシェーピング符号化 */

    AbsQuantW(iLBCenc_inst, fout,syntDenum,
        weightDenum,idxVec, len, state_first);
}

