#include "iLBC_define.h"

/*----------------------------------------------------------------*
 *  LP合成フィルター。
 *---------------------------------------------------------------*/

void syntFilter(
    float *Out,     /* (i/o) フィルタリングする信号 */
    float *a,       /* (i) LPパラメーター */
    int len,    /* (i) 信号の長さ */
    float *mem      /* (i/o) フィルター状態 */
){
    int i, j;
    float *po, *pi, *pa, *pm;

    po=Out;

    /* 過去のメモリーを使って前半部分をフィルタリング */

    for (i=0; i<LPC_FILTERORDER; i++) {
        pi=&Out[i-1];
        pa=&a[1];
        pm=&mem[LPC_FILTERORDER-1];
        for (j=1; j<=i; j++) {
            *po-=(*pa++)*(*pi--);
        }
        for (j=i+1; j<LPC_FILTERORDER+1; j++) {
            *po-=(*pa++)*(*pm--);
        }
        po++;
    }

    /* 状態がすべて出力ベクトル内にある後半部分を
       フィルタリング */

    for (i=LPC_FILTERORDER; i<len; i++) {
        pi=&Out[i-1];
        pa=&a[1];
        for (j=1; j<LPC_FILTERORDER+1; j++) {
            *po-=(*pa++)*(*pi--);
        }
        po++;
    }

    /* 状態ベクトルを更新 */

    memcpy(mem, &Out[len-LPC_FILTERORDER],
        LPC_FILTERORDER*sizeof(float));
}
